	["Blanco"] = "Blanc",
	["Blizzard no dejó copiar tu mapa desde un addon. Se abrió su ventana de clic para lanzar: arma ahí los mismos clics."] = "Blizzard n'a pas permis à un addon de copier votre configuration. Sa fenêtre de lancement par clic s'est ouverte : refaites-y les mêmes clics.",
	["Blizzard no dejó copiar tu mapa desde un addon. Ábrelo en el menú del juego: Opciones, Clic para lanzar."] = "Blizzard n'a pas permis à un addon de copier votre configuration. Ouvrez-la depuis le menu du jeu : Options, Lancement par clic.",
