	["Cambia a «Todo» para ver su botín completo."] = "Passez à « Tout » pour voir tout son butin.",
	["Cambia al mapa de Alfa en esta zona: todo el mundo en un solo mapa, con zoom y tus marcadores."] = "Passe à la carte d'Alfa sur cette zone : le monde entier sur une seule carte, avec zoom et vos marqueurs.",
