	["Clic: la flecha te lleva. Clic derecho: ya no mostrarla."] = "Clic : la flèche vous y mène. Clic droit : ne plus l'afficher.",
	["Clic: la lista de pasos. Rueda: mirar otros pasos sin cambiar nada."] = "Clic : la liste des étapes. Molette : voir d'autres étapes sans rien changer.",
