	["Colores de clase en los marcos, un cuadro de información más útil, el probador mejorado, la siguiente parada en los vuelos y sin voces de error. Cada una se apaga abajo cuando quieras."] = "Couleurs de classe sur les cadres, une infobulle plus utile, la cabine d'essayage améliorée, la prochaine étape des vols et plus de voix d'erreur. Chacune se désactive plus bas quand vous voulez.",
