	["Compañeros por columna"] = "Membres par colonne",
	["Completa el objetivo"] = "Remplissez l'objectif",
	["Completa o entrega las que tienes abiertas"] = "Terminez ou rendez celles que vous avez en cours",
	["Componentes"] = "Composants",
	["Comprar"] = "Acheter",
	["Comprar otra casilla del banco"] = "Acheter un autre emplacement de banque",
	["Comprar por %s"] = "Acheter pour %s",
	["Comunidad"] = "Communauté",
	["Común"] = "Classique",
	["Con 10 de furia o más lo lanzas."] = "Vous pouvez le lancer à partir de 10 points de rage.",
	["Con aullido"] = "Avec le hurlement",
	["Con dos armas pega más rápido: guarda maná para el final."] = "Avec deux armes, il frappe plus vite : gardez du mana pour la fin.",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "Quand l'infobulle est masquée en combat, maintenez Maj enfoncée pour la voir.",
	["Con el cursor encima no se cierra."] = "Il ne se ferme pas tant que le curseur est dessus.",
	["Con el entrenador más cercano en tu camino."] = "Avec le maître le plus proche sur votre chemin.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. Pulsa el botón y luego la tecla que quieras."] = "Elle lance votre ligne et, quand ça mord, remonte le poisson. Appuyez sur le bouton, puis sur la touche voulue.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. También está en el menú de atajos del juego, en Alfa."] = "Elle lance votre ligne et, quand ça mord, remonte le poisson. Elle est aussi dans les Raccourcis du jeu, sous Alfa.",
	["Con la caña en el agua"] = "Ligne à l'eau",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "Avec l'interface manette, la carte du jeu s'ouvre avec sa propre touche.",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "Avec l'interface pour manette, Alfa laisse les sacs du jeu. Vous pouvez quand même ouvrir la fenêtre d'Alfa d'ici.",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "Avec ceux d'Alfa, vous voyez tout dans une seule fenêtre : trois vues, la recherche, la barre de vos sacs et quoi vendre quand ils se remplissent.",
	["Con mando, se quedan las bolsas del juego"] = "Avec une manette, les sacs du jeu restent",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "Avec ou sans Maj, Ctrl ou Alt. Rien n'est lancé : vous voyez ici ce qui serait lancé sur votre allié.",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "Quand sa vie est basse, il appelle deux aides : s'il est presque mort, achevez-le ; sinon, tuez les aides.",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "Quand sa vie est basse, il se transforme en serpent et frappe plus fort : gardez vos meilleures attaques pour ce moment.",
	["Con reputación %s"] = "À la réputation %s",
	["Con sonido"] = "Avec son",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "Avec votre build, Alfa sait quelles caractéristiques vous servent et quel équipement chercher.",
	["Con tu punto libre se compra 1 rango de %s:"] = "Votre point libre achète 1 rang de %s :",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "Avec vos %d points libres, %d rangs de %s sont achetés :",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "Avec un ennemi ciblé, avant le début du combat, et transparent pour ne pas gêner.",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "Il gèle ceux qui sont proches : si vous combattez à distance, éloignez-vous.",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "Gelez le monstre avec Nova de givre et éloignez-vous avant de continuer à lancer des sorts.",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "Elle immobilise sur place et lance des éclairs : si vous combattez à distance, écartez-vous du groupe.",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "Vous gelez et ralentissez les monstres pour qu'ils ne vous atteignent jamais : le mage le plus sûr pour monter.",
	["Conjúralas fuera de combate."] = "Invoquez-les hors combat.",
	["Conseguir %d de %s"] = "Obtenir %d %s",
	["Conseguir %s"] = "Obtenir %s",
	["Consejo en el cuadro de los objetos"] = "Conseil dans l'infobulle des objets",
	["Consejos"] = "Conseils",
	["Consejos de equipo apagados."] = "Conseils d'équipement désactivés.",
	["Consejos para jugarlo"] = "Conseils pour le jouer",
	["Conserva %s: vale más de otra forma."] = "Gardez %s : il vaut plus autrement.",
	["Considerar desencantar"] = "Envisager le désenchantement",
	["Consigue %s"] = "Obtenez %s",
	["Consumibles"] = "Consommables",
	["Contenta"] = "Content",
	["Contigo"] = "Avec vous",
	["Continuar"] = "Continuer",
	["Continuar mi ruta"] = "Continuer mon itinéraire",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "Contre les boss de haut niveau, vous ratez beaucoup : ceci règle le problème.",
	["Contra jefes fallas mucho: esto te ayuda."] = "Contre les boss, vous ratez beaucoup : ceci vous aide.",
	["Control de animación"] = "Contrôle de l'animation",
	["Coordenadas en el mapa"] = "Coordonnées sur la carte",
	["Coordenadas en el minimapa"] = "Coordonnées sur la minicarte",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "Copiez ce texte (Ctrl+C) et transmettez-le à votre meute. Ils le collent dans Importer.",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "Copiez la chaîne ci-dessous et envoyez-la dans la discussion ou sur Discord : avec Alfa, ils la collent dans Importer et ont le même build que vous.",
	["Copia tu mapa al clic para lanzar de Blizzard, así curas igual en sus marcos de grupo. Si el juego no lo deja, abre su ventana para que lo hagas ahí."] = "Copie votre configuration dans le lancement par clic de Blizzard, pour soigner de la même façon sur ses cadres de groupe. Si le jeu ne le permet pas, sa fenêtre s'ouvre pour que vous le fassiez vous-même.",
	["Copiar"] = "Copier",
	["Copiar el Discord"] = "Copier le Discord",
	["Coral"] = "Corail",
	["Correr"] = "Courir",
	["Crear %s ≈ %s"] = "Fabriquer %s ≈ %s",
	["Crear ruta"] = "Créer l'itinéraire",
	["Crecen hacia"] = "S'étendent vers",
	["Criaturas de nivel %d a %d"] = "Créatures de niveau %d à %d",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "Créatures rares et trésors : où ils apparaissent et ce qu'ils laissent tomber.",
	["Cristal"] = "Cristal",
	["Crítico"] = "Critique",
	["Crítico con hechizos"] = "Critique des sorts",
	["Críticos enormes: matas antes de que te curen."] = "Des critiques énormes : vous tuez avant qu'on ne les soigne.",
	["Críticos más fuertes."] = "Des critiques plus forts.",
	["Críticos un poco más fuertes."] = "Des critiques un peu plus forts.",
	["Ctrl"] = "Ctrl",
	["Cuadro de información"] = "Infobulle",
	["Cualquier criatura de su nivel"] = "N'importe quelle créature de son niveau",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "N'importe laquelle de vos techniques que le jeu met en surbrillance grâce à un effet.",
	["Cuando Alfa acepta y entrega misiones solo, puede limitarse a las que sirven a tu ruta."] = "Quand Alfa accepte et rend les quêtes tout seul, il peut s'en tenir à celles dont votre itinéraire a besoin.",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "Quand le monstre a peu de vie, utilisez Exécution (Alfa vous prévient).",
	["Cuando aprendas %s, también."] = "Dès que vous connaîtrez %s, aussi.",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "Dès que vous connaîtrez %s, il vous prévient au moment de les utiliser.",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "Quand vous apprenez un nouveau rang, une alerte propose de le remplacer sur vos barres.",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "Quand vous cherchez quelque chose à l'hôtel des ventes, Alfa garde le prix le plus bas que vous voyez.",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "Quand vous entrez dans une auberge ou une ville, et quand votre XP de repos est épuisée.",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "Quand sa vie baisse, il étourdit tout le monde et court à son coffre changer d'arme : attendez-le, ne le poursuivez pas.",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "Quand vous portez un objet, Alfa vous dit s'il vaut mieux le vendre, le mettre aux enchères ou le transformer, et combien vous gagnez.",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "Quand un autre loup avec Alfa partage sa position, il apparaît ici et sur votre carte. Pour agrandir la meute, invitez vos amis : qu'ils installent Alfa, acceptent de partager et rejoignent le Discord de La Jauría.",
	["Cuando se llenan"] = "Quand ils se remplissent",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "Quand vous n'avez plus de mana, passez en forme de félin pour finir le combat.",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "Quand vous ou votre groupe combattez, vous voyez ici qui fait le plus de dégâts.",
	["Cuando una pieza baja de este porcentaje."] = "Quand une pièce passe sous ce pourcentage.",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "Quand vous vaincrez votre premier boss, votre progression apparaîtra ici.",
	["Cuando ya casi se rompe."] = "Quand elle est sur le point de se briser.",
	["Cuello"] = "Cou",
	["Cuenta:"] = "Compte :",
	["Cuero"] = "Cuir",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "Corps à corps avec des totems et des frappes élémentaires : le chaman qui monte le mieux.",
	["Cuesta %s (tienes %s). Es la casilla %d de %d: después pon una bolsa en ella para guardar más."] = "Coût : %s (vous avez %s). C'est l'emplacement %d sur %d : placez-y ensuite un sac pour ranger davantage.",
	["Cuesta %s."] = "Coût : %s.",
	["Cuestan %s: te alcanza."] = "Coût : %s. Vous avez assez.",
	["Cuestan %s; llevas %s."] = "Coût : %s ; vous avez %s.",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "Attention à ne pas en attirer plusieurs à la fois : Feu n'a pas autant de contrôle.",
	["Cura"] = "Soigneur",
	["Cura a quien tenga el dolor de sombras; la pelea es corta."] = "Soignez celui qui subit la douleur de l'ombre ; le combat est court.",
	["Cura a sus ayudantes y a sí misma: interrúmpanla."] = "Elle soigne ses aides et se soigne elle-même : interrompez-la.",
	["Cura a tu grupo con un clic."] = "Soignez votre groupe en un clic.",
	["Curación"] = "Soins",
	["Curación con clic"] = "Soins en un clic",
	["Curación: arrastra para mover"] = "Soins : faites glisser pour déplacer",
	["Curandero"] = "Soigneur",
	["Curas que van llegando"] = "Soins entrants",
	["Cursor"] = "Curseur",
	["Cuándo"] = "Quand",
	["Cuántas casillas caben en cada fila."] = "Combien d'emplacements tiennent sur chaque ligne.",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "Le nombre d'emplacements libres restants quand Alfa vous prévient.",
	["Cuántas habilidades después"] = "Combien de techniques ensuite",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Combien de dégâts chaque blocage absorbe ; augmente aussi les dégâts de Heurt de bouclier.",
	["Cuánto dura un aviso en pantalla"] = "Durée d'affichage d'une alerte",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Le temps restant avant votre prochaine attaque automatique, pour chaque main. Aide à placer Heurtoir ou Frappe héroïque sans perdre de coups.",
	["Cuántos en el top"] = "Combien dans le top",
	["Cuántos se anuncian"] = "Combien sont annoncés",
	["Cuántos tienes, en el cuadro de cada objeto"] = "Combien vous en avez, dans l'infobulle de chaque objet",
	["Cuántos van en cada columna (o fila) antes de empezar otra. 5 es un grupo por columna."] = "Combien en mettre dans chaque colonne (ou ligne) avant d'en commencer une autre. 5 donne un groupe par colonne.",
	["Cuéntanos qué te parece en La Jauría."] = "Dites-nous ce que vous en pensez sur La Jauría.",
	["Cámara"] = "Caméra",
	["Cómo conseguir cualquier objeto, misión o PNJ, y qué guía te lleva ahí."] = "Comment obtenir n'importe quel objet, quête ou PNJ, et quel guide vous y mène.",
	["Cómo conseguir cualquier objeto, montura, PNJ, misión o lugar."] = "Comment obtenir n'importe quel objet, monture, PNJ, quête ou lieu.",
	["Cómo conseguirlo"] = "Comment l'obtenir",
	["Cómo decide Alfa"] = "Comment Alfa décide",
	["Cómo juego"] = "Ma façon de jouer",
	["Cómo se usa"] = "Mode d'emploi",
	["Cómo se ven las zonas sin descubrir"] = "Apparence des zones non découvertes",
	["Cómo trabaja tu ruta"] = "Comment fonctionne votre itinéraire",
	["Cómprala con un vendedor."] = "Achetez-en chez un marchand.",
	["DPS"] = "DPS",
	["DPS del arma"] = "DPS de l'arme",
	["Daga"] = "Dague",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Nourrissez votre familier pour qu'il soit content et frappe plus fort.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Nourrissez-le pour qu'il soit heureux : il frappe plus fort.",
	["Datos"] = "Données",
	["Daño"] = "Dégâts",
	["Daño a distancia"] = "Dégâts à distance",
	["Daño con el tiempo: ponla al empezar la pelea."] = "Dégâts sur la durée : appliquez-le au début du combat.",
	["Daño de arcos, armas de fuego y ballestas."] = "Dégâts des arcs, armes à feu et arbalètes.",
	["Daño de fuego con el tiempo."] = "Dégâts de feu sur la durée.",
	["Daño del arma"] = "Dégâts de l'arme",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "Des dégâts directs de feu et d'ombre : vous tuez avant que le monstre n'arrive.",
	["Daño directo de tus armas y habilidades."] = "Dégâts directs de vos armes et techniques.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Des dégâts en groupe de cinq : frapper fort sans voler les monstres au tank.",
	["Daño extra después de recibir críticos."] = "Dégâts en plus après avoir subi des critiques.",
	["Daño extra después de recibir un golpe crítico."] = "Dégâts en plus après avoir subi un coup critique.",
	["Daño por segundo"] = "Dégâts par seconde",
	["De Forever"] = "Forever",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "De haut en bas : la première que le jeu vous laisse utiliser est celle de l'icône ; celles de zone, seulement avec 3 ennemis ou plus en combat.",
	["De la base de datos incluida"] = "De la base de données incluse",
	["De la otra facción"] = "Autre faction",
	["De misión"] = "De quête",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "Du niveau %.1f au %.1f, avec environ %s d'or. Seulement des quêtes que vous pouvez déjà prendre ; ce qui demande plus de niveau vient après une étape qui l'attend.",
	["Debajo del ícono: útil mientras aprendes."] = "Sous l'icône : pratique pendant l'apprentissage.",
	["Dedo"] = "Doigt",
	["Defensa"] = "Défense",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "Laissez le tank frapper quelques secondes avant d'utiliser vos gros coups.",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "Laissez votre familier commencer le combat et tirez quand le monstre l'attaque.",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Ne garde que l'essentiel : vous, votre groupe, vos marqueurs et la prochaine étape du guide.",
	["Dejar"] = "Arrêter",
	["Dejar de seguir"] = "Ne plus suivre",
	["Dejarlo como recomienda Alfa"] = "Utiliser la configuration recommandée par Alfa",
	["Del motor de Alfa: al subir de nivel te muestra qué aprender y cuánto cuesta."] = "Du moteur d'Alfa : à chaque niveau, il vous montre quoi apprendre et combien ça coûte.",
	["Del motor de Alfa: con el entrenador más cercano en tu camino."] = "Du moteur d'Alfa : avec le maître le plus proche sur votre chemin.",
	["Del preajuste"] = "Du préréglage",
	["Demonología"] = "Démonologie",
	["Demonología para subir"] = "Démonologie pour monter",
	["Dentro"] = "À l'intérieur",
	["Dentro de"] = "À l'intérieur de",
	["Dentro de la mazmorra"] = "Dans le donjon",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "Les donjons et les villes n'ont pas de nœuds. Sortez dans le monde et votre itinéraire se crée en un clic.",
	["Dentro de una instancia el juego no deja compartir: sale solo cuando salgas."] = "Dans une instance, le jeu ne permet pas de partager : c'est envoyé tout seul à votre sortie.",
	["Dentro de una instancia no se puede seguir a nadie."] = "Impossible de suivre quelqu'un à l'intérieur d'une instance.",
	["Depositar"] = "Déposer",
	["Depositar rápido"] = "Dépôt rapide",
	["Depósito detenido: guardaste %d."] = "Dépôt interrompu : %d rangés.",
	["Derecho"] = "Droit",
	["Derrota a %s"] = "Vainquez %s",
	["Desarmar más seguido: quitas el arma a los enemigos que pegan fuerte."] = "Désarmer plus souvent : vous retirez leur arme aux ennemis qui frappent fort.",
	["Desbloquear %s"] = "Débloquer %s",
	["Descansa en una posada o una ciudad para juntar más."] = "Reposez-vous dans une auberge ou une ville pour en accumuler plus.",
	["Descansando%s%d%% de un nivel"] = "Au repos%s%d%% d'un niveau",
	["Descansando: %d %%"] = "Au repos : %d %%",
	["Descanso"] = "Repos",
	["Descanso %d %%"] = "Repos %d %%",
	["Desconectado"] = "Déconnecté",
	["Descontenta"] = "Malheureux",
	["Descubriste a %s"] = "Vous avez découvert %s",
	["Descubriste a %s (%s)."] = "Vous avez découvert %s (%s).",
	["Desde cero"] = "À partir de zéro",
	["Desde cuántas habilidades"] = "À partir de combien de compétences",
	["Desde el nivel 10"] = "Dès le niveau 10",
	["Desde el nivel 20"] = "Dès le niveau 20",
	["Desde nivel %d"] = "Dès le niveau %d",
	["Desencantar ≈ %s"] = "Désenchanter ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "Désenchanter : ≈ %s par objet%s. Nécessite Enchantement %d.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "Pourfendre fait plus de dégâts pendant que le monstre saigne ; il vous le faut pour Blessures profondes.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "Pourfendre fait plus de dégâts ; il vous le faut pour Blessures profondes.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "Pourfendre vous prépare plus de Fulgurances : plus de coups impossibles à esquiver.",
	["Deshacer"] = "Annuler",
	["Desmarcar"] = "Décocher",
	["Después"] = "Plus tard",
	["Después de cada golpe, regresa a tu lugar rápido."] = "Après chaque projection, revenez vite à votre place.",
	["Después de estos siguen %d más."] = "%d autres suivent ceux-ci.",
	["Después de otra"] = "Après une autre",
	["Después de tu segunda pelea, aquí ves la de antes."] = "Après votre deuxième combat, vous voyez ici le précédent.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "Après un critique, vous attaquez plus vite : plus de coups, plus de rage.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "Après lui, les braseros de l'autel s'allument et des vagues d'ennemis arrivent : préparez-vous avant.",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "Après le premier boss, un prisonnier de votre faction ouvre la porte : parlez-lui.",
	["Después sigue"] = "Ensuite",
	["Después: %d %% del nivel %d"] = "Après : %d %% du niveau %d",
	["Después: nivel %d"] = "Après : niveau %d",
	["Destino"] = "Destination",
	["Destrucción"] = "Destruction",
	["Destrucción para subir"] = "Destruction pour monter",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "Vous dépecez ce que vous tuez et le transformez en armures de cuir pour vous ; le reste se vend.",
	["Desuello"] = "Dépeçage",
	["Desvías golpes con tu arma."] = "Vous détournez les coups avec votre arme.",
	["Detalle al pasar el ratón"] = "Détails au survol",
	["Detalle fino de cada zona"] = "Détail fin de chaque zone",
	["Detener"] = "Arrêter",
	["Detener (%d/%d)"] = "Arrêter (%d/%d)",
	["Devolver los avisos a su lugar"] = "Remettre les alertes à leur place",
	["Diario"] = "Journal",
	["Diario de mazmorras"] = "Journal des donjons",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "Dessine l'illustration complète de chaque zone découpée à sa forme, avec les textures de détail incluses. Sans elles, la carte reste complète, juste plus floue entre les zones.",
	["Dinero de toda la cuenta"] = "Argent de tout le compte",
	["Dinero de tus personajes"] = "Argent de vos personnages",
	["Disciplina"] = "Discipline",
	["Disciplina para subir"] = "Discipline pour monter",
	["Dispara desde lejos: alguien debe ir por él."] = "Il tire de loin : quelqu'un doit aller le chercher.",
	["Disparo apuntado: tu disparo más fuerte."] = "Visée : votre tir le plus puissant.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "Tir des Arcanes : instantané, utilisez-le dès qu'il est prêt.",
	["Disponible a nivel %d"] = "Disponible au niveau %d",
	["Doble clic derecho"] = "Double-clic droit",
	["Doble clic derecho para lanzar"] = "Double-clic droit pour lancer",
	["Doble clic mientras pescas vuelve a lanzar"] = "Un double-clic pendant la pêche relance la ligne",
	["Dominio de bestias"] = "Maîtrise des bêtes",
	["Dominio de bestias para subir"] = "Maîtrise des bêtes pour monter",
	["Dormir"] = "Dormir",
	["Dos armas"] = "Deux armes",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "Deux armes et beaucoup de rage. Fureur frappe plus fort qu'Armes quand il est bien équipé, et Sanguinaire arrive au niveau 40. Il vous faut deux armes à une main dès le niveau 20.",
	["Dos clics y Alfa te lleva"] = "Deux clics et Alfa vous y mène",
	["Dos manos"] = "Deux mains",
	["Dos monstruos a la vez dejan de ser un problema."] = "Deux monstres à la fois ne sont plus un problème.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "Deux métiers de récolte : de l'or régulier sans perdre de temps, juste quand vous en avez le plus besoin.",
	["Drenar alma al rematar te da uno."] = "Siphon d'âme pour achever une cible vous en donne un.",
	["Druida"] = "Druide",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "Il endort un joueur et lance des sorts d'ombre : interrompez-le.",
	["Duplicar"] = "Dupliquer",
	["Durabilidad"] = "Durabilité",
	["Duración"] = "Durée",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "Pendant le combat, il réveille des gardiens de pierre : quelqu'un doit les tanker, ou tuez-les vite.",
	["Dónde"] = "Où",
	["Dónde entregar"] = "Où rendre",
	["Dónde está"] = "Où c'est",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "Où se trouve chacun, ce qu'il vend, ce qu'il laisse tomber et ses quêtes.",
	["Dónde se entrega"] = "Où la rendre",
	["Dónde se ven"] = "Où ils s'affichent",
	["Ejecutar cuesta menos ira: rematas antes."] = "Exécution coûte moins de rage : vous achevez plus tôt.",
	["Ejecutar más barato para rematar jefes."] = "Exécution moins chère pour achever les boss.",
	["El Discord de La Jauría"] = "Le Discord de La Jauría",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "L'endurance est votre meilleure amie : plus de vie pour plus de Connexion.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "L'arme en main droite doit être la plus lente et la plus forte ; celle en main gauche, la plus rapide.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "La banque est pleine : achetez un autre emplacement ou mettez un sac plus grand dans la banque.",
	["El bonus de tu arma al máximo."] = "Le bonus de votre arme au maximum.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "La bordure prend la couleur de l'effet néfaste (magie, malédiction, maladie ou poison) quand vous pouvez le dissiper.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "Le bouton « Scanner avec Alfa » sous la fenêtre de l'hôtel des ventes.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "La Recherche du moteur est désactivée (Réglages > Découverte) : activez-la pour qu'Alfa puisse créer des guides.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "Le chemin vers l'objectif sur la carte du monde et la minicarte : une ligne ou des points là où vous marchez, des lignes là où vous volez, naviguez ou chevauchez, et les tronçons suivants plus pâles.",
	["El camino hasta el destino dibujado en el mapa."] = "Le chemin jusqu'à la destination, tracé sur la carte.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "La façon la plus simple de monter : une grande arme, des coups qui font saigner et Frappe mortelle au niveau 40. Vous encaissez bien et tuez vite.",
	["El clan"] = "Le clan",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "Un simple clic droit continue de dézoomer la carte du jeu, comme toujours.",
	["El clic izquierdo solo selecciona"] = "Le clic gauche ne fait que cibler",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "Le classique pour combattre les joueurs : Frappe mortelle réduit les soins de l'adversaire, Brise-genou amélioré l'immobilise et Charge améliorée vous donne de la rage pour commencer.",
	["El color de mi clase"] = "La couleur de ma classe",
	["El comerciante no lo compra"] = "Le marchand ne l'achète pas",
	["El corcho está en el agua. Cuando se hunda, haz clic derecho sobre él para recoger."] = "Le flotteur est dans l'eau. Quand il plonge, faites un clic droit dessus pour remonter le poisson.",
	["El corcho está en el agua. Cuando se hunda, pulsa %s para recoger."] = "Le flotteur est dans l'eau. Quand il plonge, appuyez sur %s pour remonter le poisson.",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "L'infobulle du joueur au survol. Elle ne s'affiche pas en combat, pour ne pas gêner.",
	["El daño por segundo de tu arma a distancia."] = "Les dégâts par seconde de votre arme à distance.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "Les dégâts par seconde de l'arme : pour le guerrier, ce qui compte le plus en montant de niveau.",
	["El destino de la flecha y sus zonas en el minimapa."] = "La destination de la flèche et ses zones sur la minicarte.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "La destination de la flèche, son chemin et les autres objectifs de l'étape, sur la carte.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "Le journal des donjons du moteur est désactivé (Réglages > Découverte > Donjons).",
	["El diario de mazmorras está apagado"] = "Le journal des donjons est désactivé",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "L'ennemi a esquivé : Fulgurance ne peut pas être esquivée et frappe fort.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "L'ennemi a esquivé : cette frappe au corps à corps est prête.",
	["El enemigo esquivó: este golpe está listo."] = "L'ennemi a esquivé : ce coup est prêt.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "L'ennemi est sur vous : frappez-le au corps à corps.",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "L'esprit vous rend vite du mana : vous vous reposez très peu.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "Le feu touche tous ceux qui sont proches : gardez haute la vie de ceux qui combattent au corps à corps.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "Le guerrier qui fait le plus de dégâts en donjon. Avec un tank devant, vos deux armes ne s'arrêtent jamais, et Exécution améliorée achève les boss.",
	["El izquierdo selecciona y el derecho abre el menú."] = "Le gauche cible et le droit ouvre le menu.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Le gauche cible et le droit ouvre le menu. Vous choisissez le reste.",
	["El izquierdo selecciona y el derecho abre el menú; tu clase no tiene buffs para otros."] = "Le gauche cible et le droit ouvre le menu ; votre classe n'a pas de buffs pour les autres.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "Le jeu choisit parmi celles-ci selon la situation ; l'icône vous montre la plus utile maintenant.",
	["El juego la hizo brillar: es buen momento para usarla."] = "Le jeu l'a fait briller : c'est le bon moment pour l'utiliser.",
	["El juego no aceptó esa tecla."] = "Le jeu a refusé cette touche.",
	["El juego no aceptó la prueba."] = "Le jeu n'a pas accepté le test.",
	["El juego no deja cambiar talentos ahora mismo"] = "Le jeu ne permet pas de changer de talents pour l'instant",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "Le jeu ne permet pas d'envoyer de messages en ce moment (une rencontre ou une partie). Votre piste repart toute seule à la fin.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "Le jeu ne permet pas aux comptes d'essai d'envoyer des messages d'addon ni d'utiliser des canaux personnalisés. Votre groupe reste visible.",
	["El juego no dejó cambiar las demás."] = "Le jeu n'a pas permis de modifier les autres.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "Le jeu n'a pas permis de partager le marqueur pour l'instant. Réessayez dans un moment.",
	["El juego no dejó comprar ese rango."] = "Le jeu n'a pas permis d'acheter ce rang.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "Le jeu n'a pas laissé entrer dans le canal caché d'Alfa et, sans guilde, il n'y a pas d'autre moyen de partager. Alfa réessaie tout seul dans quelques minutes. Votre groupe reste visible.",
	["El juego no la ofrece ahora mismo."] = "Le jeu ne la propose pas en ce moment.",
	["El juego no lo dice ahora."] = "Le jeu ne l'indique pas pour l'instant.",
	["El juego no permite usar el medidor ahora."] = "Le jeu ne permet pas d'utiliser le compteur pour l'instant.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "Le jeu n'inclut pas l'assistant de combat de Blizzard : Alfa suggère donc avec sa propre priorité pour %s, en lisant seulement votre personnage : votre ressource, vos effets et ce que le jeu vous laisse utiliser. Avec 3 ennemis ou plus, il passe aux techniques de zone. C'est vous qui décidez sur quoi appuyer.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "Le jeu masque les chiffres exacts pendant le combat : la barre et le chiffre restent visibles, le détail à la sortie du combat.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Le jeu a refusé de confirmer les changements. Ils ont été annulés pour que votre arbre reste comme avant.",
	["El juego todavía no carga tu árbol"] = "Le jeu n'a pas encore chargé votre arbre",
	["El juego todavía no carga tu árbol."] = "Le jeu n'a pas encore chargé votre arbre.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Le jeu n'a pas encore chargé vos talents. Attendez quelques secondes ou ouvrez une fois la fenêtre des talents (touche N).",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "Le jeu n'a pas encore les données de certains objets. Elles arrivent dans un instant.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "Le jeu masque encore les chiffres ou les noms (c'est le cas en combat et dans les donjons). Réessayez une fois sorti.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Le mage qui fait le plus de dégâts : sorts de feu et critiques qui brûlent.",
	["El mapa a tu gusto"] = "La carte à votre goût",
	["El mapa de Alfa"] = "La carte d'Alfa",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "La carte d'Alfa, celle du jeu et la minicarte. Si quelque chose vous gêne, désactivez-le ici ; les autres modules d'Alfa ajoutent leurs calques à cette même liste.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "La carte du monde entier avec zoom, vos marqueurs et un seul réglage pour tout ce qui y est dessiné.",
	["El mapa no se abre en combate."] = "La carte ne s'ouvre pas en combat.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "Le médaillon sous chaque marque de la carte et de la minicarte : celui d'Alfa ou le symbole seul, sans médaillon.",
	["El medidor no está disponible"] = "Le compteur n'est pas disponible",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "Le menu de la loupe de la carte du jeu contient aussi tous les calques d'Alfa.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "La minicarte passe de ronde à carrée, avec une bordure fine. Déconseillé avec la rotation de la minicarte.",
	["El modelo no lleva nada aquí."] = "Le modèle ne porte rien ici.",
	["El modo prueba se usa fuera de combate."] = "Le mode test s'utilise hors combat.",
	["El motor no aceptó la guía."] = "Le moteur n'a pas accepté le guide.",
	["El motor no puede armar guías ahora."] = "Le moteur ne peut pas créer de guides pour l'instant.",
	["El mundo entero en un mapa"] = "Le monde entier sur une carte",
	["El módulo Curación no está cargado."] = "Le module Soins n'est pas chargé.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Le nom de chaque zone sur la carte d'Alfa.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Le nombre en bas à gauche de chaque pièce d'équipement.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "Le numéro indique l'ordre dans lequel on le prend. Survolez un talent pour voir ce qu'il fait.",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "L'objet qu'utilise l'étape en cours, ou l'objet de quête qu'elle fait ramasser, brille dans vos sacs. Un objet requis par une étape ultérieure reçoit un cadenas, pour que vous ne le vendiez pas.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "L'ordre compte plus que les chiffres : cherchez des pièces avec les premières de la liste.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Le pack de données d'Alfa (Alfa_Codex) est désactivé : activez-le dans la liste des addons et rechargez.",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Le voleur le plus facile pour monter : il frappe de face, esquive beaucoup et encaisse mieux que les autres.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "La tranche de niveaux de chaque zone, colorée selon votre niveau.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "Le suivi vous indique la prochaine étape et la flèche vous y mène.",
	["El registro de daño del juego está apagado"] = "Le suivi des dégâts du jeu est désactivé",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "Le suivi des dégâts du jeu est désactivé : activez-le pour voir le top de votre groupe.",
	["El reino limita los mensajes de addon salientes: %s"] = "Le royaume limite les messages d'addon sortants : %s",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Le soigneur des chamans : soins en chaîne et totems qui aident tout le groupe.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Le soigneur des druides : vous soignez n'importe quel groupe et survivez bien, même si en solo vous tuez lentement.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Le soigneur des paladins : soins puissants et beaucoup d'armure, idéal en groupe.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Le soigneur pur : gros soins et soins pour tout le groupe.",
	["El sistema de equipo de Alfa no está disponible."] = "Le système d'équipement d'Alfa n'est pas disponible.",
	["El talento que toca"] = "Votre prochain talent",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Le tank classique : vous bloquez beaucoup, générez de la menace avec Vengeance et Heurt de bouclier, et avez Dernier rempart quand tout tourne mal.",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Le tank le plus dur à tuer : tous les talents de défense, Mur protecteur amélioré et Dernier rempart tôt. Parfait pour débuter comme tank.",
	["El texto es demasiado largo."] = "Le texte est trop long.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Le texte est arrivé coupé ou modifié : copiez-le à nouveau.",
	["El tipo de nodos que une la ruta."] = "Le type de nœuds que relie l'itinéraire.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "La teinte des fonds : Graphite est celle d'Alfa, Nuit la plus sombre et Ardoise un gris neutre.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "Le top DPS de votre groupe ou raid dans une petite fenêtre, avec le combat actuel et le précédent.",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "L'arbre d'itinéraire d'Alfa, les quêtes à mesure qu'elles se débloquent et un catalogue d'objets.",
	["El último punto: paras un poco más."] = "Le dernier point : vous parez un peu plus.",
	["Elegido"] = "Choisi",
	["Elegido por ti"] = "Choisi par vous",
	["Elegir capas"] = "Choisir les calques",
	["Elegir la siguiente guía"] = "Choisir le guide suivant",
	["Elegir mi camino"] = "Choisir mon chemin",
	["Elegir mi primera guía"] = "Choisir mon premier guide",
	["Elegir mi tecla"] = "Choisir ma touche",
	["Elegir otra guía"] = "Choisir un autre guide",
	["Elegir qué sigue"] = "Choisir la suite",
	["Elegir una guía"] = "Choisir un guide",
	["Elemental"] = "Élémentaire",
	["Elemental para subir"] = "Élémentaire pour monter",
	["Elfos de la noche"] = "Elfes de la nuit",
	["Elige algo de la lista"] = "Choisissez quelque chose dans la liste",
	["Elige el objeto"] = "Choisissez l'objet",
	["Elige el objeto en la Enciclopedia."] = "Choisissez l'objet dans l'Encyclopédie.",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "Choisissez quoi ranger : ce que vous avez déjà à la banque, les matériaux, une catégorie ou tout ce qui n'est pas de l'équipement. Tout part d'un coup, hors combat.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "Choisissez ce que vous voulez faire et Alfa vous guide pas à pas.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "Choisissez ce qu'affiche la carte : guide, quêtes, rares, voyages, zones et ce qu'ajoutent les autres modules.",
	["Elige solo misiones que ya puedes tomar."] = "Il ne choisit que des quêtes que vous pouvez déjà prendre.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "Choisissez votre chemin. Si vous hésitez, commencez par monter de niveau : Alfa vous dit ce qui est rentable.",
	["Elige tu estilo"] = "Choisissez votre style",
	["Elige tu tecla para pescar"] = "Choisissez votre touche de pêche",
	["Elige tus clics"] = "Choisissez vos clics",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "Choisissez vos clics, placez vos cadres et testez-les. Cela prend une minute.",
	["Elige tú la zona."] = "Vous choisissez la zone.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "Choisissez un chemin : Alfa prépare votre plan et vous guide pas à pas.",
	["Elige una guía para empezar"] = "Choisissez un guide pour commencer",
	["Elige uno y lo ves al instante en todas las ventanas de Alfa, también la flecha."] = "Choisissez-en un et voyez-le aussitôt dans toutes les fenêtres d'Alfa, flèche comprise.",
	["Eliges una"] = "Une au choix",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Elle endort tout le groupe puis ressuscite Mograine : c'est normal, pas de panique.",
	["Embate con escudo: mucho daño y amenaza."] = "Heurt de bouclier : beaucoup de dégâts et de menace.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Heurtoir ne réinitialise plus votre attaque : un coup en plus entre deux coups.",
	["Embate sin perder tu ataque automático."] = "Heurtoir sans perdre votre attaque automatique.",
	["Embate sin perder tu ataque."] = "Heurtoir sans perdre votre attaque.",
	["Embate sin perder tu golpe automático."] = "Heurtoir sans perdre votre coup automatique.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Heurtoir sans réinitialiser votre attaque : un coup en plus.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "Heurtoir : un coup puissant entre deux attaques.",
	["Empezar"] = "Commencer",
	["Empezar de cero"] = "Repartir de zéro",
	["Empezar de nuevo"] = "Recommencer",
	["Empezó %s"] = "Commencée %s",
	["Empezó %s."] = "Commencée %s.",
	["Empieza al usar este objeto"] = "Commence quand vous utilisez cet objet",
	["Empieza aquí"] = "Commencez ici",
	["Empieza con %s, que se consigue en la mazmorra."] = "Elle commence avec %s, qui s'obtient dans le donjon.",
	["Empieza con %s, que suelta %s."] = "Elle commence avec %s, laissé par %s.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Commencez de loin avec votre sort le plus lent et finissez avec les instantanés.",
	["Empieza dentro"] = "Commence à l'intérieur",
	["Empieza una misión"] = "Commence une quête",
	["Empiezas: nivel %d"] = "Vous commencez : niveau %d",
	["En 9 idiomas"] = "En 9 langues",
	["En camino"] = "En route",
	["En combate"] = "En combat",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "En combat, le jeu masque les chiffres exacts : les barres et les chiffres restent visibles ; le détail et l'annonce, à la sortie du combat.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "En combat, la carte du jeu ne s'ouvre pas depuis Alfa : utilisez celle d'Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "En combat, l'infobulle des personnages et des créatures du monde n'apparaît pas (celle des cadres reste affichée).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "Pas de test en combat : quittez le combat et revenez à cette étape.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "En combat, l'icône montre la technique suggérée par l'assistant de combat de Blizzard et les %d suivantes. C'est vous qui décidez sur quoi appuyer : Alfa n'appuie jamais à votre place.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "En combat, l'icône montre la technique suggérée par l'assistant de combat de Blizzard. C'est vous qui décidez sur quoi appuyer : Alfa n'appuie jamais à votre place.",
	["En combate: espera a terminar"] = "En combat : attendez la fin",
	["En curso"] = "En cours",
	["En el camino"] = "Sur le chemin",
	["En el chat"] = "Dans la discussion",
	["En el juego"] = "Dans le jeu",
	["En el mapa"] = "Sur la carte",
	["En el mapa del mundo"] = "Sur la carte du monde",
	["En el marco del objetivo"] = "Sur le cadre de la cible",
	["En el minimapa"] = "Sur la minicarte",
	["En el mundo"] = "Dans le monde",
	["En el nivel 10 domas tu bestia."] = "Au niveau 10, vous apprivoisez votre bête.",
	["En el nivel 20 aprendes venenos."] = "Au niveau 20, vous apprenez les poisons.",
	["En esta zona"] = "Dans cette zone",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "En groupe, il y a presque toujours plusieurs ennemis : vous en frappez deux à la fois.",
	["En grupo, cura al tanque antes que a nadie."] = "En groupe, soignez le tank avant tout le monde.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "En groupe, soignez d'abord le tank et n'attirez pas de monstres vous-même.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "En groupe, soignez avant que la vie ne baisse trop : ça coûte moins cher.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "En groupe, posez vos totems de mana et de soins près du groupe.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "Dans la grotte du navire, il y a beaucoup de pirates : ne descendez pas tous d'un coup sur le quai.",
	["En la pelea, el juego te avisa"] = "Pendant le combat, le jeu vous prévient",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Dans la deuxième partie, tuez-la en premier : elle soigne beaucoup.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Pour l'hôtel des ventes, il compte le prix le plus bas vu, moins la commission (%d%%, estimée). Pour le désenchantement, il utilise les tables du jeu classique, estimées elles aussi.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "Dans la fenêtre et ici. Si vous n'en faites pas partie, votre ligne apparaît à la fin.",
	["En las dos armas"] = "Sur les deux armes",
	["En los mapas"] = "Sur les cartes",
	["En lugar de las del juego"] = "À la place de ceux du jeu",
	["En marcha"] = "En cours",
	["En marcha hacia %s"] = "En route vers %s",
	["En mazmorra"] = "En donjon",
	["En mazmorras y bandas"] = "Dans les donjons et raids",
	["En mi zona"] = "Dans ma zone",
	["En otra zona: %s"] = "Dans une autre zone : %s",
	["En pantalla"] = "À l'écran",
	["En pausa"] = "En pause",
	["En pausa dentro de la instancia"] = "En pause dans l'instance",
	["En pausa por ahora"] = "En pause pour l'instant",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "Dans les auberges et les villes, vous accumulez de l'XP de repos : vous gagnez le double d'XP par ennemi jusqu'à l'épuiser. Si vous vous déconnectez ici, elle s'accumule aussi.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "Dans les auberges et les villes, vous accumulez de l'XP de repos : le double d'XP par ennemi jusqu'à épuisement.",
	["En qué orden aparecen."] = "L'ordre dans lequel ils apparaissent.",
	["En solitario es lento: usa la varita para rematar."] = "En solo, c'est lent : utilisez la baguette pour achever.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "En solo, posez des soins sur la durée et combattez avec Colère.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "En solo, combattez avec les horions et soignez-vous entre deux monstres.",
	["En su ficha toca «Agregar a mi ruta»."] = "Sur sa fiche, touchez « Ajouter à mon itinéraire ».",
	["En tu arma"] = "Sur votre arme",
	["En tu marco"] = "Sur votre cadre",
	["En tu plan"] = "Dans votre plan",
	["En tu registro"] = "Dans votre journal",
	["En tus bolsas"] = "Dans vos sacs",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "Dans vos sacs, le butin, la discussion ou n'importe quel lien : Alt+clic ouvre le guide pour l'obtenir ou, s'il n'y en a pas, sa fiche dans l'encyclopédie.",
	["En un aviso"] = "En alerte",
	["En un aviso y en el chat"] = "En alerte et dans la discussion",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "Sur un vol avec escales, une ligne sous le minuteur indique la prochaine étape et le temps restant pour y arriver. Nécessite le minuteur de vol activé.",
	["En una instancia: la flecha vuelve al salir"] = "Dans une instance : la flèche revient à la sortie",
	["En una pestaña nueva"] = "Dans un nouvel onglet",
	["En unos segundos aparece tu build."] = "Votre build apparaît dans quelques secondes.",
	["En uso"] = "Utilisé",
	["En uso, a tu gusto"] = "Utilisé, à votre façon",
	["En vivo"] = "En direct",
	["En vivo si estás con un banquero; si no, la última foto."] = "En direct si vous êtes chez un banquier ; sinon, le dernier relevé.",
	["En vuelo: la flecha sigue al bajar"] = "En vol : la flèche reprend à l'atterrissage",
	["En vuelo: la flecha sigue al bajar."] = "En vol : la flèche reprend à l'atterrissage.",
	["Enanos"] = "Nains",
	["Encanta tu arma antes de pelear."] = "Enchantez votre arme avant de combattre.",
	["Encantada"] = "Enchantée",
	["Encantamiento"] = "Enchantement",
	["Encender el registro"] = "Activer le suivi",
	["Encender la pesca"] = "Activer la pêche",
	["Encender las recomendadas"] = "Activer celles recommandées",
	["Encenderla"] = "L'activer",
	["Encenderlos"] = "Les activer",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "Activée : elle entre dans le plan même si le filtre l'exclut. Désactivée : elle reste exclue.",
	["Encendido"] = "Activé",
	["Encendido y tecla"] = "Activation et touche",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "Activé : un double-clic pendant la pêche relance la ligne et, avec Maj, Ctrl ou Alt, remonte le poisson. Désactivé : l'inverse.",
	["Enciclopedia"] = "Encyclopédie",
	["Enciende las comodidades recomendadas"] = "Activez les options de confort recommandées",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "Active les changements ci-dessous dans l'infobulle qui s'affiche quand vous survolez un personnage ou une créature.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Active les changements ci-dessous dans la cabine d'essayage (Ctrl + clic sur un objet).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Active les changements ci-dessous ; chacun peut être désactivé séparément. Certains addons placent leurs boutons sur la minicarte carrée après un /reload.",
	["Enciende primero la guía en el minimapa."] = "Activez d'abord le guide sur la minicarte.",
	["Enciende primero los servicios."] = "Activez d'abord les services.",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "Activez-la pour voir en combat quelle technique est la plus utile maintenant et lesquelles suivent, dans une petite icône déplaçable.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "Activez-les ci-dessous, dans Cadres, pour voir la vie de votre groupe et soigner en un clic.",
	["Enciéndelos en la página Curación."] = "Activez-les sur la page Soins.",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "Activez-les pour voir la vie de votre groupe et soigner en un clic.",
	["Enemigo raro"] = "Ennemi rare",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "Immobilisez le monstre et éloignez-vous avant de lancer vos sorts longs.",
	["Entendido"] = "Compris",
	["Entereza"] = "Robustesse",
	["Entra al juego con él una vez."] = "Connectez-vous une fois avec lui.",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "Entrez avec un journal propre : rendez ce que vous avez déjà.",
	["Entrada"] = "Entrée",
	["Entrada enemiga"] = "Entrée ennemie",
	["Entradas de mazmorras"] = "Entrées de donjon",
	["Entradas en el minimapa"] = "Entrées sur la minicarte",
	["Entraste a %s"] = "Vous êtes entré dans %s",
	["Entraste a %s."] = "Vous êtes entré dans %s.",
	["Entrega tus %d misiones listas"] = "Rendez vos %d quêtes terminées",
	["Entregar"] = "Rendre",
	["Entregar las completadas"] = "Rendre les quêtes terminées",
	["Entregar mis misiones"] = "Rendre mes quêtes",
	["Entregar misiones"] = "Rendre les quêtes",
	["Entregar solas las misiones de la guía"] = "Rendre automatiquement les quêtes du guide",
	["Entregarlas ahora"] = "Les rendre maintenant",
	["Entrenador"] = "Maître",
	["Entrenador al día"] = "Maître à jour",
	["Entrenador: %s, en %s."] = "Maître : %s, à %s.",
	["Entrenador: %s."] = "Maître : %s.",
	["Entrégala a %s."] = "Rendez-la à %s.",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "Il empoisonne et lance des éclairs : guérissez le poison si vous le pouvez.",
	["Equilibrada"] = "Équilibrée",
	["Equilibrado"] = "Équilibré",
	["Equilibrio"] = "Équilibre",
	["Equilibrio para subir"] = "Équilibre pour monter",
	["Equipa tu caña de pescar"] = "Équipez votre canne à pêche",
	["Equipo"] = "Équipement",
	["Equipo %d %%"] = "Équipement %d %%",
	["Equipo a punto de romperse."] = "Équipement sur le point de se briser.",
	["Equipo y estadísticas"] = "Équipement et caractéristiques",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "Équipement, consommables, quêtes, matériaux... sous des en-têtes repliables.",
	["Eres de la manada"] = "Vous faites partie de la meute",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "Vous êtes niveau %d et le niveau %d est recommandé : à partir de là, voici le calcul.",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Le donjon est court et se trouve dans Stormwind. Les prisonniers sont dans des cellules de chaque côté : avancez lentement.",
	["Es de la otra facción"] = "Elle est de l'autre faction",
	["Es de una misión."] = "C'est un objet de quête.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "C'est le boss demandé par une quête de l'Alliance : vérifiez vos quêtes avant d'entrer.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "C'est le premier boss, et il est simple. À sa mort, le prisonnier de votre faction ouvre la porte de la cour.",
	["Es el punto %d de %d de tu build."] = "C'est le point %d sur %d de votre build.",
	["Es el que toca ahora."] = "C'est celui à prendre maintenant.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "C'est le dernier du Cimetière. Il lance des flammes autour de lui : si vous combattez à distance, restez loin.",
	["Es el único lobo a la vista."] = "C'est le seul loup en vue.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Il est grand et on s'y perd facilement : suivez une seule personne et ne partez pas seul.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "C'est la machine de Sneed : détruisez-la et il sortira se battre.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "C'est le premier donjon de la Horde : court et idéal pour apprendre à jouer en groupe.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "C'est le premier grand donjon de l'Alliance : avancez lentement et attirez un groupe à la fois.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Il est long et a deux entrées. Beaucoup d'ennemis sont en pierre et frappent fort.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Il est long et plein de robots : certains posent des bombes ou déclenchent des alarmes qui font venir plus d'ennemis.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Il est lent : si vous combattez à distance, attaquez-le pendant qu'il approche.",
	["Es muy veloz: frénalo si tu clase puede."] = "Il est très rapide : ralentissez-le si votre classe le peut.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "C'est pour les niveaux %s et vous êtes niveau %d : encore %d niveaux.",
	["Es para otra raza."] = "C'est pour une autre race.",
	["Es raro del Cementerio y no siempre aparece."] = "C'est un rare du Cimetière, il n'apparaît pas toujours.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "C'est un rare du Cimetière, il n'apparaît pas toujours. Il empoisonne : guérissez le poison.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "C'est un rare du Cimetière, il n'apparaît pas toujours. Il peut réduire au silence les lanceurs de sorts.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "C'est un rare qui se montre peu. Il utilise du feu autour de lui.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "C'est un rare, caché dans une grotte. C'est une chauve-souris qui frappe vite.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "C'est un rare, il n'apparaît pas toujours. Il frappe très fort pour son niveau : attirez-le avec prudence.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "C'est un rare, il n'est pas toujours là. Il frappe fort tous ceux qui sont devant lui.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "C'est un rare. Il pose un totem de terre : détruisez-le.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "C'est un rare, il n'est pas toujours là. Il endort les joueurs et explose de magie autour de lui.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Il est simple : bon moment pour boire avant le dernier boss.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "C'est un lanceur de sorts : interrompez-le si votre classe le peut (Coup de pied, Coup de bouclier, Horion de terre...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "C'est un chaman avec des totems : détruisez les totems, ils meurent vite.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "C'est un nain avec un bouclier : il encaisse beaucoup, mais sans surprise.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "C'est un ennemi coriace de la mine : traitez-le comme un petit boss.",
	["Es un grupo: cada uno suelta su propio botín."] = "C'est un groupe : chacun laisse tomber son propre butin.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "C'est un paladin : il se soigne avec Lumière sacrée. Interrompez son soin.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "C'est un satyre rapide qui empoisonne : si votre classe guérit les poisons, faites-le.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "C'est un trogg qui lance des éclairs : interrompez-le.",
	["Es una mejora para ti"] = "C'est une amélioration pour vous",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "C'est une tortue géante très cuirassée : elle frappe lentement mais fort.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "C'est une tortue très résistante, mais elle ne fait que frapper : aucune surprise.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "Cette chaîne ne contient aucune statistique notée par Alfa.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Cette rangée n'est pas encore ouverte : il manque des points dans cette branche.",
	["Esa tecla ya tiene dueño"] = "Cette touche est déjà prise",
	["Escala de estadísticas"] = "Échelle de statistiques",
	["Escalas:"] = "Escales :",
	["Escaneando..."] = "Scan en cours...",
	["Escanear ahora"] = "Scanner maintenant",
	["Escanear con Alfa"] = "Scanner avec Alfa",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Scan complet : %s objets avec un prix (%s enchères).",
	["Escarcha"] = "Givre",
	["Escarcha para subir"] = "Givre pour monter",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Masque les barres de nom et les noms des PNJ pendant la pêche (les ennemis hostiles gardent leur nom), pour mieux voir et atteindre le flotteur.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Masque ce qui demande plus de compétence que vous n'en avez. Sans cela, ils s'affichent en gris et pâles.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "Tapez %s ou cliquez sur le loup de la minicarte pour l'ouvrir. Elle s'ouvre sur Aujourd'hui, avec ce dont votre classe a besoin ; %s affiche ou masque la fenêtre du guide.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "Tapez %s et dites-le-nous sur le Discord de La Jauría.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "Tapez le nom d'un donjon ci-dessus pour le trouver.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "Écrit le top %d dans la discussion de votre groupe ou raid.",
	["Escribe un nombre corto para reconocerla."] = "Tapez un nom court pour le reconnaître.",
	["Escribir a %s"] = "Écrire à %s",
	["Escuchar"] = "Écouter",
	["Escuchar el aullido"] = "Écouter le hurlement",
	["Escudo"] = "Bouclier",
	["Escudo de relámpagos"] = "Bouclier de foudre",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Bouclier et défense : vous retenez tous les monstres pour que votre groupe ne souffre pas.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Bouclier et lumière sacrée : un tank très résistant qui récupère son propre mana.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Boucliers et soins préventifs : vous encaissez beaucoup et soutenez le groupe.",
	["Ese build es para otra clase."] = "Ce build est pour une autre classe.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Ce talent exige d'abord un autre talent complet (la flèche de l'arbre).",
	["Ese texto es demasiado largo para un build."] = "Ce texte est trop long pour un build.",
	["Ese texto es demasiado largo para una cadena de escala."] = "Ce texte est trop long pour une chaîne d'échelle.",
	["Ese texto no es una ruta de Alfa."] = "Ce texte n'est pas un itinéraire d'Alfa.",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Ce n'est pas une chaîne de build d'Alfa. Elle commence par ALFA1;",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "Ce n'est pas une chaîne d'échelle de statistiques. Elle commence par ( Pawn: v1: \"Nom\": ...",
	["Espacio libre"] = "Espace libre",
	["Espacio y dinero"] = "Place et argent",
	["Espada de dos manos"] = "Épée à deux mains",
	["Espada de una mano"] = "Épée à une main",
	["Espalda"] = "Dos",
	["Español, inglés y siete idiomas más, en toda la interfaz."] = "Espagnol, anglais et sept autres langues, dans toute l'interface.",
	["Espera %s"] = "Attendez %s",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "Attendez que le tank ait bien l'ennemi en main avant de frapper fort.",
	["Espera a salir de combate para probarla."] = "Attendez d'être hors combat pour la tester.",
	["Espera a salir de combate."] = "Attendez d'être hors combat.",
	["Espera a terminar de entrar al juego."] = "Attendez d'être entièrement connecté.",
	["Espera · nivel %d"] = "En attente · niveau %d",
	["Espera: %s."] = "En attente : %s.",
	["Esperan: %s."] = "En attente : %s.",
	["Espíritu"] = "Esprit",
	["Esquiva"] = "Esquive",
	["Esquivar"] = "Esquive",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "Cette classe n'a pas de pondérations de statistiques dans Alfa.",
	["Esta clase no tiene pesos de estadísticas."] = "Cette classe n'a pas de pondérations de statistiques.",
	["Esta sesión"] = "Cette session",
	["Esta sesión, por recurso"] = "Cette session, par ressource",
	["Esta sesión: %s"] = "Cette session : %s",
	["Esta subasta no permite el escaneo completo."] = "Cet hôtel des ventes ne permet pas le scan complet.",
	["Estadísticas"] = "Caractéristiques",
	["Este banco no vende más espacio."] = "Cette banque ne vend plus de place.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Ce build frappe extrêmement fort, mais encaisse peu : choisissez bien le moment d'entrer.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "Ce clic ne fait rien. Choisissez-lui une action dans Votre souris, sur la page Soins.",
	["Este cliente no da el arte del mapa"] = "Ce client ne fournit pas les images de la carte",
	["Este cliente no deja compartir"] = "Ce client ne permet pas de partager",
	["Este cliente no deja compartir marcadores."] = "Ce client ne permet pas de partager des marqueurs.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Ce client ne peut pas copier votre configuration tout seul : la fenêtre de lancement par clic de Blizzard s'est ouverte pour que vous la fassiez là.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "Ce client n'a pas le lancement par clic de Blizzard. Vos clics fonctionnent sur les cadres d'Alfa.",
	["Este paso no tiene punto en el mapa."] = "Cette étape n'a pas de point sur la carte.",
	["Este talento no está en tu build."] = "Ce talent ne fait pas partie de votre build.",
	["Este tramo quedó vacío."] = "Ce tronçon est vide.",
	["Estilo y sonido"] = "Style et son",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Impossible de changer cela en combat. Réessayez à la fin du combat.",
	["Esto no se puede vincular."] = "Impossible de créer un lien pour ceci.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Il est dans le Cimetière. Il inflige une douleur de l'ombre qui fait des dégâts sur la durée.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Il est dans l'eau, près de la cascade : amenez-le sur la terre ferme avant de combattre.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Il est dans l'Armurerie. Quand il crie, il tournoie avec sa hache et frappe tous ceux qui sont proches : éloignez-vous.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Il est dans la Bibliothèque et arrive avec ses chiens : tuez-les d'abord ou utilisez des attaques de zone.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Il est caché dans la Cathédrale. Il lance des malédictions et se soigne : interrompez-le.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Il est plein de hurans et de tunnels d'épines : attirez-en peu à la fois.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Il est entouré de gobelins au travail : attirez d'abord ces gobelins, un par un.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Il est entouré de murlocs : attirez ses amis avant lui.",
	["Estás aquí"] = "Vous êtes ici",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Vous êtes chez un banquier : depuis sa fenêtre, déposez ce que vous voulez en un clic.",
	["Estás dentro"] = "Vous êtes à l'intérieur",
	["Estás descansando"] = "Vous êtes au repos",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Vous êtes en combat. Les talents ne se changent que hors combat : finissez le combat et réessayez.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Vous êtes en combat : cherchez l'équipement à la fin du combat.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Vous êtes en combat : vos changements s'appliqueront à la sortie du combat.",
	["Estás en una instancia: la flecha vuelve al salir."] = "Vous êtes dans une instance : la flèche revient à la sortie.",
	["Estás mirando otro paso"] = "Vous regardez une autre étape",
	["Evento"] = "Événement",
	["Evita golpes críticos y aplastantes: lo más importante para un tanque."] = "Évite les coups critiques et écrasants : le plus important pour un tank.",
	["Evitar misiones de grupo"] = "Éviter les quêtes de groupe",
	["Experiencia"] = "Expérience",
	["Explicar por qué"] = "Expliquer pourquoi",
	["Fallas menos golpes, sobre todo contra monstruos de nivel más alto que el tuyo."] = "Vous ratez moins de coups, surtout contre les monstres de niveau supérieur au vôtre.",
	["Fallas menos golpes."] = "Vous ratez moins de coups.",
	["Fallas menos: con dos armas fallas mucho sin esto."] = "Vous ratez moins : avec deux armes, vous ratez beaucoup sans cela.",
	["Fallida"] = "Échouée",
	["Falta el final del texto: cópialo completo."] = "La fin du texte manque : copiez-le en entier.",
	["Falta el paquete de datos de Alfa (Alfa_Codex): vuelve a instalar Alfa completo."] = "Le pack de données d'Alfa (Alfa_Codex) est manquant : réinstallez Alfa en entier.",
	["Falta en un arma"] = "Manque sur une arme",
	["Falta la carpeta Alfa_Codex: reinstala Alfa."] = "Le dossier Alfa_Codex est manquant : réinstallez Alfa.",
	["Falta la función del juego para enviar mensajes de addon. Tu grupo sí se ve."] = "La fonction du jeu pour envoyer des messages d'addon est absente. Votre groupe reste visible.",
	["Faltan las texturas de detalle en la carpeta Media de Alfa_Mundo: el mapa se dibuja solo con el arte del juego."] = "Les textures de détail manquent dans le dossier Media d'Alfa_Mundo : la carte est dessinée uniquement avec l'illustration du jeu.",
	["Faltan los datos de las mazmorras"] = "Les données des donjons sont manquantes",
	["Faltan precios"] = "Prix manquants",
	["Faltan precios de algunos materiales."] = "Il manque le prix de certains matériaux.",
	["Faltan precios de sus materiales: escanea la subasta."] = "Il manque le prix de ses matériaux : scannez l'hôtel des ventes.",
	["Fantasma"] = "Fantôme",
	["Feliz"] = "Heureux",
	["Fija"] = "Épinglée",
	["Fijar"] = "Épingler",
	["Fijar marcos"] = "Verrouiller les cadres",
	["Filones y depósitos de mineral."] = "Filons et gisements de minerai.",
	["Fin de tu ruta: arma la siguiente en la página Ruta de Alfa."] = "Fin de votre itinéraire : créez le suivant sur la page Itinéraire d'Alfa.",
	["Fin del camino"] = "Fin de la piste",
	["Final de %s"] = "Fin de %s",
	["Flecha de mejora"] = "Flèche d'amélioration",
	["Flecha puesta"] = "Flèche placée",
	["Flechas"] = "Flèches",
	["Fondos transparentes para ver el mundo detrás y el color de acento que elijas."] = "Des fonds transparents qui laissent voir le monde derrière, dans la couleur d'accent de votre choix.",
	["Forma"] = "Forme",
	["Forma felina para matar rápido y forma de oso para las peleas difíciles; casi nunca necesitas beber."] = "Forme de félin pour tuer vite et forme d'ours pour les combats difficiles ; vous n'avez presque jamais besoin de boire.",
	["Forma normal"] = "Forme normale",
	["Foto: %s"] = "Relevé : %s",
	["Fragmentos de alma"] = "Fragments d'âme",
	["Frena a los que huyen y te deja escapar de una mala pelea."] = "Ralentit ceux qui fuient et vous permet d'échapper à un mauvais combat.",
	["Frena a los que huyen y te salva de malas peleas."] = "Ralentit ceux qui fuient et vous sauve des mauvais combats.",
	["Frena a todos los rivales cercanos."] = "Ralentit tous les adversaires proches.",
	["Fuego"] = "Feu",
	["Fuego interno"] = "Feu intérieur",
	["Fuego para subir"] = "Feu pour monter",
	["Fuera de combate es el mejor momento"] = "Hors combat, c'est le meilleur moment",
	["Fuera de este plan: %s (%s)."] = "Hors de ce plan : %s (%s).",
	["Fuera de tu plan de misiones"] = "Hors de votre plan de quêtes",
	["Fuera del plan"] = "Hors du plan",
	["Fuerza"] = "Force",
	["Furia"] = "Fureur",
	["Furia con dos armas"] = "Fureur à deux armes",
	["Furia con todo el daño posible: más precisión, Ejecutar mejorado y críticos enormes. Muy rápido matando, pero frágil."] = "Fureur avec tous les dégâts possibles : plus de toucher, Exécution améliorée et critiques énormes. Très rapide pour tuer, mais fragile.",
	["Furia contra jugadores"] = "Fureur JcJ",
	["Furia desatada"] = "Fureur déchaînée",
	["Furia para grupo"] = "Fureur en groupe",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "Fureur pour combattre les joueurs : énormément de dégâts, Rage berserker améliorée contre la peur et Interception plus souvent pour ne pas lâcher l'adversaire.",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "Rage sanguinaire vous donne plus de rage pour commencer les combats difficiles.",
	["Gana un poco de XP y Alfa calcula cuánto te falta."] = "Gagnez un peu d'XP et Alfa calculera ce qu'il vous reste.",
	["Gana un poco de XP y Alfa lo calcula"] = "Gagnez un peu d'XP et Alfa fait le calcul",
	["Ganado"] = "Gagné",
	["Ganado %s"] = "Gagné %s",
	["Ganado: %s. Gastado: %s. Suma tus sesiones de hoy con este personaje."] = "Gagné : %s. Dépensé : %s. Cumule les sessions du jour avec ce personnage.",
	["Ganas de más"] = "Or en plus",
	["Garra: suma puntos de combo."] = "Griffe : génère des points de combo.",
	["Gasta la ira sobrante en Golpe heroico; si llegas a 100 de ira, la estás desperdiciando."] = "Dépensez la rage en trop dans Frappe héroïque ; si vous atteignez 100 de rage, vous la gaspillez.",
	["Gastado"] = "Dépensé",
	["General, por categorías o por bolsa, y depósito rápido al banco."] = "Vue d'ensemble, par catégorie ou par sac, et dépôt rapide à la banque.",
	["Gnomos"] = "Gnomes",
	["Golpe"] = "Toucher",
	["Golpe con hechizos"] = "Toucher des sorts",
	["Golpe crítico"] = "Coup critique",
	["Golpe fuerte que además reduce las curas del rival."] = "Une frappe puissante qui réduit aussi les soins de l'adversaire.",
	["Golpe heroico cuesta menos ira: lo usarás en cada pelea."] = "Frappe héroïque coûte moins de rage : vous l'utiliserez à chaque combat.",
	["Golpe heroico más barato."] = "Frappe héroïque moins chère.",
	["Golpe heroico más barato: amenaza extra con la ira que sobra."] = "Frappe héroïque moins chère : menace en plus avec la rage en trop.",
	["Golpe heroico más barato: la ira sobrante se vuelve amenaza."] = "Frappe héroïque moins chère : la rage en trop devient de la menace.",
	["Golpe heroico: tu golpe más fuerte mientras subes."] = "Frappe héroïque : votre coup le plus puissant pendant la montée de niveau.",
	["Golpe mental: mucho daño, cada vez que esté listo."] = "Attaque mentale : gros dégâts, dès qu'elle est prête.",
	["Golpe mortal: tu golpe más fuerte, cada vez que esté listo."] = "Frappe mortelle : votre coup le plus puissant, dès qu'il est prêt.",
	["Golpe siniestro: suma puntos de combo."] = "Attaque pernicieuse : génère des points de combo.",
	["Golpea a los que tiene alrededor: gíralo lejos del grupo."] = "Il frappe ceux qui l'entourent : tournez-le loin du groupe.",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "Il frappe tous ceux qui sont proches et les repousse : si vous combattez au corps à corps, surveillez votre vie.",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "Il frappe tous ceux qui sont devant lui : attaquez de dos si vous combattez au corps à corps.",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "Il frappe tous ceux qui sont devant lui : au corps à corps, attaquez par derrière.",
	["Golpea a varios enemigos a tu alrededor."] = "Frappe plusieurs ennemis autour de vous.",
	["Golpea fuerte con su cuchilla y hace sangrar: vigila la vida del tanque."] = "Il frappe fort avec son couperet et provoque des saignements : surveillez la vie du tank.",
	["Golpea y avienta al tanque: regresa a tu lugar rápido."] = "Il frappe et repousse le tank : revenez vite à votre place.",
	["Golpea y frena a todos los enemigos que tienes cerca."] = "Frappe et ralentit tous les ennemis proches.",
	["Golpeas a dos a la vez: puedes juntar monstruos de dos en dos."] = "Vous frappez deux ennemis à la fois : vous pouvez attirer les monstres deux par deux.",
	["Grafito"] = "Graphite",
	["Grafito con esquinas cortadas y el verde de La Jauría. El de siempre."] = "Graphite aux coins coupés et le vert de La Jauría. Le style de toujours.",
	["Gran aumento de daño para los jefes."] = "Gros bonus de dégâts pour les boss.",
	["Gran aumento de daño y te libra del miedo."] = "Gros bonus de dégâts, et vous libère de la peur.",
	["Gran aumento de daño."] = "Gros bonus de dégâts.",
	["Gran golpe de escudo con mucha amenaza."] = "Un grand coup de bouclier avec beaucoup de menace.",
	["Gratis"] = "Gratuit",
	["Gratis tras vencer a un enemigo, y te cura."] = "Gratuite après avoir vaincu un ennemi, et elle vous soigne.",
	["Grito de batalla"] = "Cri de guerre",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "Cri de guerre pour le guerrier ; Intelligence des Arcanes et une armure pour le mage ; Robustesse et Feu intérieur pour le prêtre ; et ce qu'il faut pour chaque classe.",
	["Grupo"] = "Groupe",
	["Grupo de %d"] = "Groupe de %d",
	["Grupo de 5"] = "Groupe de 5",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "Gardez %d quêtes : vous les rendrez dans un guide suivant.",
	["Guarda Grito intimidador para cuando estés en peligro."] = "Gardez Cri d'intimidation pour quand vous êtes en danger.",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "Gardez Mur protecteur pour les pires moments du boss.",
	["Guardar"] = "Garder",
	["Guardar %d"] = "Garder %d",
	["Guardar como marcador"] = "Enregistrer comme marqueur",
	["Guardar y seguir"] = "Enregistrer et suivre",
	["Guardas ira al cambiar de actitud."] = "Vous gardez de la rage en changeant de posture.",
	["Guardas tu ira al cambiar de actitud; así Cargar, Abrumar y Revancha salen casi gratis."] = "Vous gardez votre rage en changeant de posture : Charge, Fulgurance et Vengeance sont presque gratuites.",
	["Guardaste %d objeto en el banco."] = "Vous avez rangé %d objet à la banque.",
	["Guardaste %d objetos en el banco."] = "Vous avez rangé %d objets à la banque.",
