	["No entregué %s: pide oro o monedas. Entrégala tú si quieres."] = "Je n'ai pas rendu %s : elle demande de l'or ou des monnaies. Rendez-la vous-même si vous voulez.",
	["No es para ti"] = "Pas pour vous",
	["No es para tu clase"] = "Pas pour votre classe",
	["No es para tu raza"] = "Pas pour votre race",
	["No está en tu árbol"] = "Absent de votre arbre",
	["No están en tu árbol y se saltan: %s."] = "Absents de votre arbre, ignorés : %s.",
	["No estás siguiendo a nadie."] = "Vous ne suivez personne.",
	["No hay guías así"] = "Aucun guide de ce genre",
	["No hay misiones para ti cerca de aquí. Prueba en el pueblo más cercano o sigue tu ruta."] = "Aucune quête pour vous par ici. Essayez le village le plus proche ou suivez votre itinéraire.",
	["No hay misiones que convenga dejar"] = "Aucune quête qui vaille la peine d'être abandonnée",
	["No hay misiones que puedas tomar ahora: te llevo a la entrada."] = "Aucune quête à prendre pour l'instant : je vous mène à l'entrée.",
	["No hay nada que comprar: o ya tienes todo lo del plan hasta tu nivel, o no tienes puntos libres."] = "Rien à acheter : soit vous avez déjà tout le plan jusqu'à votre niveau, soit vous n'avez pas de points libres.",
	["No hay nodos conocidos en esta zona."] = "Aucun nœud connu dans cette zone.",
	["No hay un build exacto para %s y %s: este es el que más se parece."] = "Il n'y a pas de build exact pour %s et %s : voici le plus proche.",
	["No hay un camino que Alfa pueda guiar para esto."] = "Alfa ne peut guider aucun chemin pour ceci.",
	["No la agregué"] = "Je ne l'ai pas ajoutée",
	["No la usas"] = "Non utilisées",
	["No llevas chatarra para vender."] = "Vous n'avez pas de camelote à vendre.",
	["No llevas nada para depositar con esa opción."] = "Rien à déposer avec cette option.",
	["No llevas nada que convenga vender: guarda algo en el banco."] = "Rien qui vaille la peine d'être vendu : rangez quelque chose à la banque.",
	["No llevas nada que depositar"] = "Rien à déposer",
	["No lo puedes usar todavía"] = "Vous ne pouvez pas encore l'utiliser",
	["No mostrar"] = "Ne pas afficher",
	["No muestra los ataques que todavía tardan mucho: la barra queda más limpia."] = "N'affiche pas les attaques encore lointaines : la barre est plus lisible.",
	["No muestra los ataques que ya deberían haber llegado y esperan su momento."] = "N'affiche pas les attaques qui devraient déjà être arrivées et attendent leur moment.",
	["No pegaste nada."] = "Vous n'avez rien collé.",
	["No pude armar esa guía"] = "Je n'ai pas pu créer ce guide",
	["No pude armar la ruta"] = "Je n'ai pas pu créer l'itinéraire",
	["No pude leer dónde estás."] = "Je n'ai pas pu lire où vous êtes.",
	["No pude preparar la ruta"] = "Je n'ai pas pu préparer l'itinéraire",
	["No pudimos unirnos al canal de la manada"] = "Impossible de rejoindre le canal de la meute",
	["No quedan puntos libres."] = "Plus de points libres.",
	["No resaltarlo"] = "Ne pas le mettre en surbrillance",
	["No sabemos dónde está %s. Solo se puede seguir a tu grupo y a quien comparte su ubicación con Alfa."] = "Nous ne savons pas où est %s. Vous ne pouvez suivre que votre groupe et ceux qui partagent leur position avec Alfa.",
	["No se aplicaron los talentos"] = "Les talents n'ont pas été appliqués",
	["No se conoce de dónde sale."] = "On ne sait pas d'où il vient.",
	["No se conoce ningún Alfa más reciente. La app de CurseForge o la página de versiones lo dicen con seguridad."] = "Aucun Alfa plus récent n'est connu. L'application CurseForge ou la page des versions vous le diront à coup sûr.",
	["No se conoce su botín"] = "Son butin n'est pas connu",
	["No se encontró el chat."] = "Fenêtre de discussion introuvable.",
	["No se encontró la carpeta Alfa_Codex. Reinstala Alfa completo."] = "Dossier Alfa_Codex introuvable. Réinstallez Alfa en entier.",
	["No se encontró nada mejor cerca de tu nivel. Vuelve a buscar al subir unos niveles."] = "Rien de mieux trouvé autour de votre niveau. Cherchez à nouveau dans quelques niveaux.",
	["No se pudieron leer los datos del juego."] = "Impossible de lire les données du jeu.",
	["No se pudo"] = "Impossible",
	["No se pudo abrir el Codex de Alfa (la base de objetos). Revisa que el addon Alfa Codex esté activado."] = "Impossible d'ouvrir le Codex d'Alfa (la base d'objets). Vérifiez que l'addon Alfa Codex est activé.",
	["No se pudo armar la guía (%s)."] = "Impossible de construire le guide (%s).",
	["No se pudo buscar el lugar más cercano."] = "Impossible de trouver le lieu le plus proche.",
	["No se pudo comprar: %s"] = "Achat impossible : %s",
	["No se pudo leer el escaneo. Intenta de nuevo más tarde."] = "Impossible de lire le scan. Réessayez plus tard.",
	["No se pudo marcar: falta el motor de Alfa."] = "Impossible de marquer : il manque le moteur d'Alfa.",
	["No se pudo probar ahora"] = "Test impossible pour l'instant",
	["No se puede dibujar el mapa continuo. El mapa del juego sigue funcionando con todas las capas de Alfa."] = "Impossible de dessiner la carte continue. La carte du jeu fonctionne toujours avec tous les calques d'Alfa.",
	["No se puede en combate."] = "Impossible en combat.",
	["No se puede ordenar en combate."] = "Impossible de trier en combat.",
	["No se puede vender."] = "Ne peut pas être vendu.",
	["No se pueden cambiar bolsas en combate."] = "Impossible de changer de sac en combat.",
	["No se sabe en qué lugar está."] = "On ne sait pas où il se trouve.",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "Il n'apparaît pas toujours dans la mine : si vous le voyez, c'est un boss de plus avec un bon butin.",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "Il n'apparaît pas toujours. Il inflige une douleur de l'ombre : soignez celui qui l'a.",
	["No sigues ninguna guía"] = "Vous ne suivez aucun guide",
	["No son para ti"] = "Pas pour vous",
	["No sé de dónde sale este objeto."] = "Je ne sais pas d'où vient cet objet.",
	["No sé dónde se entrega"] = "Lieu de rendu inconnu",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "Je ne sais pas où se rend %s : je l'ai retirée de l'itinéraire.",
	["No sé dónde se entrega %s: la saqué del plan."] = "Je ne sais pas où se rend %s : je l'ai retirée du plan.",
	["No sé dónde se junta este material."] = "Je ne sais pas où se récolte ce matériau.",
	["No sé dónde se junta: búscalo en la Enciclopedia para ver de dónde sale."] = "Je ne sais pas où ça se récolte : cherchez-le dans l'Encyclopédie pour voir d'où il vient.",
	["No sé en qué zona estás."] = "Je ne sais pas dans quelle zone vous êtes.",
	["No sé qué misión es."] = "Je ne sais pas de quelle quête il s'agit.",
	["No sé si se puede tomar"] = "Je ne sais pas si elle peut être prise",
