	["Nuestra manada en Discord: ayuda, avisos y reportes. Haz clic en el enlace y cópialo con Ctrl+C."] = "Notre meute sur Discord : aide, annonces et signalements. Cliquez sur le lien et copiez-le avec Ctrl+C.",
