	["Ocultarlo en combate"] = "La masquer en combat",
	["Ocultas"] = "Masquées",
	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "Masquées comme dans le jeu, révélées, ou révélées dans un ton plus froid pour savoir où vous n'êtes pas encore allé.",
