	["Ojo con tu plan"] = "Attention à votre plan",
	["Ojo con tu ruta"] = "Attention à votre itinéraire",
	["Ojo: tu clic para lanzar de Blizzard usa %d de estas teclas, y ese manda también aquí. Para igualarlos, usa «Usar también en los marcos de Blizzard»."] = "Attention : le lancement par clic de Blizzard utilise %d de ces clics, et il a aussi la priorité ici. Pour les harmoniser, utilisez « Utiliser aussi sur les cadres de Blizzard ».",
	["Olvidar"] = "Oublier",
	["Olvidar mi progreso aquí"] = "Oublier ma progression ici",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él con Anterior."] = "Passe cette étape : le guide continue avec la suivante. Vous pouvez y revenir avec Précédent.",
