	["Opcional"] = "Optionnel",
	["Opciones de Mundo"] = "Options de Monde",
	["Orcos"] = "Orcs",
	["Orden"] = "Ordre",
	["Ordenar"] = "Trier",
	["Ordenar de derecha a izquierda"] = "Trier de droite à gauche",
