	["Otras opciones"] = "Autres options",
	["Otro addon de bolsas está activo"] = "Un autre addon de sacs est activé",
	["Otro addon de pesca está activo"] = "Un autre addon de pêche est activé",
	["Otro addon de pesca está activo. Para que no choquen, la pesca de Alfa queda en pausa: desactiva uno de los dos en la lista de addons."] = "Un autre addon de pêche est activé. Pour éviter les conflits, la pêche d'Alfa est en pause : désactivez l'un des deux dans la liste des addons.",
	["Otro golpe fuerte para tu rotación."] = "Une autre frappe puissante pour votre rotation.",
	["Otro golpe fuerte."] = "Une autre frappe puissante.",
	["Otros"] = "Autres",
	["Otros addons pueden poner puntos de ruta"] = "Laisser d'autres addons placer des points de passage",
	["Otros caminos"] = "Autres chemins",
	["PNJ"] = "PNJ",
	["PNJ %d"] = "PNJ %d",
	["Paladín"] = "Paladin",
	["Panel de estadísticas"] = "Panneau des statistiques",
	["Para abandonar"] = "À abandonner",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "Pour l'ouvrir avec la touche de la carte, activez « Ouvrir la carte d'Alfa avec la touche de la carte » plus bas.",
	["Para alguien de tu hermandad, agrega su rango."] = "Pour un membre de votre guilde, ajoute son rang.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Pour chaque objet, Alfa compare trois options : le vendre au marchand, le mettre aux enchères ou le transformer (avec une recette que vous connaissez ou en le désenchantant).",
	["Para comprar espacio, habla con un banquero."] = "Pour acheter de la place, parlez à un banquier.",
	["Para conservar"] = "À garder",
	["Para depositar, habla con un banquero."] = "Pour déposer, parlez à un banquier.",
	["Para empezar"] = "Pour commencer",
	["Para entregar"] = "À rendre",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "Il n'y en a pas avec ce style pour votre choix : Alfa utilise le plus proche.",
	["Para mi nivel (±3)"] = "Pour mon niveau (±3)",
	["Para mí"] = "Pour moi",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "Pour éviter les conflits, Alfa ne remplace pas vos sacs tant qu'il est activé. Vous pouvez quand même ouvrir la fenêtre d'Alfa d'ici.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Pour ne pas voir votre groupe en double. Se change hors combat.",
	["Para pescar necesitas una caña en las manos. Cuando la tengas puesta, ya puedes lanzar."] = "Pour pêcher, il vous faut une canne à pêche en main. Une fois équipée, vous pouvez lancer.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "Pour éviter les conflits, Alfa ne prend pas votre touche et ne modifie pas vos réglages. Désactivez l'un des deux dans la liste des addons (écran de sélection des personnages) et rechargez. Si vous gardez Alfa, il reprendra tout seul la touche que vous utilisiez dans l'autre addon.",
	["Para que no dejes botín tirado por falta de espacio."] = "Pour ne jamais laisser de butin faute de place.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "Pour ceux qui préfèrent cibler au clic gauche : le soin de ce clic passe au bouton central. Votre préréglage est réappliqué.",
	["Para recoger ahora"] = "À récupérer maintenant",
	["Para subir de nivel"] = "Avant le prochain niveau",
	["Para ti"] = "Pour vous",
	["Para tu %s"] = "Pour votre %s",
	["Para tu nivel"] = "Pour votre niveau",
	["Para tu nivel (%d)"] = "Pour votre niveau (%d)",
	["Para tu nivel ahora"] = "Pour votre niveau maintenant",
	["Para vender"] = "À vendre",
	["Para vender, habla con un comerciante."] = "Pour vendre, parlez à un marchand.",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "Pour en accumuler à nouveau, reposez-vous (ou déconnectez-vous) dans une auberge ou une ville.",
	["Parada"] = "Parade",
	["Parada %d de %d"] = "Étape %d sur %d",
	["Parar"] = "Parade",
	["Paras más golpes de otros guerreros y pícaros."] = "Vous parez plus de coups des autres guerriers et des voleurs.",
	["Paras más golpes."] = "Vous parez plus de coups.",
	["Paras más golpes: recibes menos daño desde el principio."] = "Vous parez plus de coups : vous subissez moins de dégâts dès le début.",
	["Paras un poco más."] = "Vous parez un peu plus.",
	["Paraste un golpe: el contraataque está listo."] = "Vous avez paré un coup : la contre-attaque est prête.",
	["Paraste un golpe: tu contraataque está listo y desarma al enemigo."] = "Vous avez paré un coup : votre contre-attaque est prête et désarme l'ennemi.",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "Vous avez paré un coup : votre contre-attaque immobilise l'ennemi.",
	["Pasa el ratón sobre un compañero y cúralo con un clic."] = "Survolez un allié et soignez-le d'un clic.",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "Survolez un membre du groupe et cliquez : le gauche %s et le droit %s.",
	["Pasa enfermedades: quítalas si tu clase puede."] = "Il transmet des maladies : guérissez-les si votre classe le peut.",
	["Pasa tu build a un amigo o usa el que te pasen."] = "Donnez votre build à un ami ou utilisez celui qu'on vous donne.",
	["Paso %d"] = "Étape %d",
	["Paso %d de %d"] = "Étape %d sur %d",
	["Pasos que siguen, numerados"] = "Étapes suivantes, numérotées",
	["Pausa"] = "Pause",
	["Pecho"] = "Torse",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "Collez ici (Ctrl+V) le texte d'un itinéraire d'Alfa.",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "Collez ici une chaîne qui commence par ALFA1; (Ctrl + V) et appuyez sur Importer. Alfa vérifie chaque talent dans votre arbre.",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "Il frappe fort mais sans surprise : c'est un bon boss pour apprendre.",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "Il frappe fort et se protège avec un bouclier de lumière : commencez avec toute votre vie.",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "Il frappe le tank de nombreuses fois de suite : ne laissez pas sa vie passer sous la moitié.",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "Il frappe très fort : commencez le combat avec toute votre vie.",
	["Pega primero una cadena de build de Alfa."] = "Collez d'abord une chaîne de build d'Alfa.",
	["Pega primero una cadena de escala de estadísticas."] = "Collez d'abord une chaîne d'échelle de statistiques.",
	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "Collez une chaîne d'échelle de statistiques (Ctrl+V), celle que vous avez copiée là où elle a été partagée.",
	["Pega varias veces seguidas: empieza con la vida llena."] = "Il frappe plusieurs fois de suite : commencez avec toute votre vie.",
	["Pegas a dos: útil contra mascotas y grupos."] = "Vous frappez deux cibles : utile contre les familiers et les groupes.",
	["Pegas más después de recibir críticos."] = "Vous frappez plus fort après avoir subi des critiques.",
	["Pegas más fuerte después de recibir críticos."] = "Vous frappez plus fort après avoir subi des critiques.",
	["Pegas más fuerte después de recibir un golpe crítico."] = "Vous frappez plus fort après avoir subi un coup critique.",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "Combattez un seul monstre à la fois ; si deux arrivent, utilisez Attaques circulaires.",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "Combattez toujours avec toute votre vie ; n'enchaînez pas les monstres sans vous reposer.",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "Combattre d'autres joueurs : encaisser, ralentir et achever.",
	["Peletería"] = "Travail du cuir",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "Le Travail du cuir fabrique du cuir avec armure et endurance pour la forme d'ours.",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "Le Travail du cuir fabrique des mailles pour vous ; le Dépeçage vous fournit les matériaux sans dépenser d'or.",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "Le Travail du cuir fabrique des pièces de cuir avec agilité et endurance ; le Dépeçage vous fournit le cuir.",
	["Peligro"] = "Danger",
	["Peligrosa para tu nivel"] = "Dangereuse pour votre niveau",
	["Pendiente"] = "À faire",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "De petites icônes sur chaque attaque : si elle vise le tank ou le soigneur, si elle peut être dissipée ou si elle est mortelle.",
