	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "Posez Brise-genou dès que vous atteignez l'adversaire et maintenez-le.",
	["Pon ahora"] = "À prendre maintenant",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "Posez tous vos sorts de dégâts sur la durée et laissez votre démon encaisser.",
	["Pon tu escudo y tu daño en el tiempo antes de que el monstruo llegue."] = "Posez votre bouclier et vos dégâts sur la durée avant que le monstre n'arrive.",
	["Pon tus tótems al empezar cada pelea grande."] = "Posez vos totems au début de chaque gros combat.",
	["Pon un tótem antes de empezar la pelea."] = "Posez un totem avant de commencer le combat.",
	["Pon una trampa antes de empezar la pelea y lleva al monstruo hacia ella."] = "Posez un piège avant de commencer le combat et attirez le monstre dedans.",
