	["Pone el enlace en el chat."] = "Met le lien dans la discussion.",
	["Pone la flecha ahí."] = "Place la flèche ici.",
	["Pone los marcos donde estaban al instalar Alfa."] = "Remet les cadres là où ils étaient à l'installation d'Alfa.",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos. Para moverla: menú del juego (Esc) > Modo de edición."] = "Place trois attaques de test sur la chronologie pour que vous voyiez où elle s'affiche. Elles s'effacent toutes seules. Pour la déplacer : menu du jeu (Échap) > Mode Édition.",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "Il lance une malédiction qui réduit les soins que vous recevez : dissipez-la si votre classe le peut.",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "Il lance une malédiction qui vous affaiblit et un feu qui brûle peu à peu : dissipez la malédiction si vous le pouvez.",
	["Poner la flecha aquí"] = "Placer la flèche ici",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "Tournez-le dos au groupe pour que son coup ne touche que vous.",
