	["Pulsa %s para lanzar. Cuando el corcho se hunda, pulsa %s otra vez para recoger."] = "Appuyez sur %s pour lancer. Quand le flotteur plonge, appuyez de nouveau sur %s pour remonter le poisson.",
	["Pulsa Guiarme y la flecha te lleva de parada en parada desde la más cercana."] = "Appuyez sur Me guider et la flèche vous mène d'étape en étape, en commençant par la plus proche.",
