	["Quedó sin pasos: agrega tramos o recalcula."] = "Il ne reste aucune étape : ajoutez des tronçons ou recalculez.",
	["Quema al enemigo un rato."] = "Brûle l'ennemi pendant un moment.",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "Ceux qui utilisent Alfa dans votre groupe le reçoivent et peuvent le suivre.",
	["Quienes comparten su ubicación contigo. Un clic en su marca y la flecha te lleva."] = "Ceux qui partagent leur position avec vous. Un clic sur leur marque et la flèche vous y mène.",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras ni por canales públicos."] = "Ceux qui utilisent Alfa et partagent vous voient sur leur carte et peuvent vous suivre, et vous de même. Votre zone, votre position, votre niveau et votre classe sont envoyés toutes les 10 secondes quand vous bougez (toutes les 4 minutes si vous êtes immobile), jamais dans les donjons ni par des canaux publics.",
