	["Recomendado por Alfa"] = "Recommandé par Alfa",
	["Recomienda el camino que te deja más oro, si gana por lo menos un 10 % a venderlo. Si nada da oro, te dice que lo guardes. Alfa nunca vende ni compra por ti."] = "Il recommande l'option qui vous rapporte le plus d'or, si elle bat la vente au marchand d'au moins 10 %. Si rien ne rapporte d'or, il vous dit de garder l'objet. Alfa ne vend et n'achète jamais à votre place.",
	["Recompensa de misión"] = "Récompense de quête",
