	["Tamaño del ícono"] = "Taille de l'icône",
	["Tamaño en el mapa"] = "Taille sur la carte",
	["Tamaño en el minimapa"] = "Taille sur la minicarte",
	["También con /alfa dps. No se cierra con Esc, para que la tengas a la vista al pelear."] = "Aussi avec /alfa dps. Elle ne se ferme pas avec Échap, pour rester visible pendant le combat.",
	["También cuando el juego hace brillar otra habilidad"] = "Aussi quand le jeu fait briller une autre technique",
	["También en el minimapa"] = "Aussi sur la minicarte",
	["También en montura"] = "Aussi sur une monture",
	["También fuera de combate"] = "Aussi hors combat",
	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "Aussi celles qui ne viennent pas du guide (« Accepter les quêtes du guide » s'occupe de celles-là). Les quêtes grises sont ignorées, celles qui demandent de l'or, des monnaies ou des matériaux d'artisanat ne sont pas rendues, et s'il y a plusieurs récompenses, c'est vous qui choisissez. Maintenez Maj enfoncée pour le faire vous-même.",
	["También puedes lanzar con doble clic derecho."] = "Vous pouvez aussi lancer par double-clic droit.",
	["Tanque"] = "Tank",
	["Tanque de amenaza"] = "Tank de menace",
	["Tanque de escudo"] = "Tank bouclier",
	["Tanque muralla"] = "Tank rempart",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "Fiche des nouvelles compétences à chaque niveau",
	["Tauren"] = "Taurens",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "Nous avons ouvert un chuchotement pour %s avec votre message. Vérifiez-le et appuyez sur Entrée pour l'envoyer.",
	["Te avisa al momento de %s."] = "Vous prévient au moment d'utiliser %s.",
	["Te da %s."] = "Vous donne %s.",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "Vous donne de la puissance d'attaque : chaque coup frappe plus fort. Pour le guerrier, elle augmente aussi le blocage au bouclier.",
	["Te damos la bienvenida a Alfa, el todo en uno de La Jauría."] = "Bienvenue dans Alfa, le tout-en-un de La Jauría.",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "Vous indique quelle pièce va se briser, pour la réparer à temps.",
	["Te enseña %s."] = "Vous apprend %s.",
	["Te falta"] = "Manquant",
	["Te falta %s"] = "Il vous manque %s",
	["Te falta 1 paso"] = "Encore 1 étape",
	["Te falta Aspecto del halcón: más poder a distancia."] = "Il vous manque Aspect du faucon : plus de puissance à distance.",
	["Te falta Bendición de poderío: más poder de ataque."] = "Il vous manque Bénédiction de puissance : plus de puissance d'attaque.",
	["Te falta Escudo de relámpagos."] = "Il vous manque Bouclier de foudre.",
	["Te falta Escudo sagrado: bloqueas más."] = "Il vous manque Bouclier sacré : vous bloquez davantage.",
	["Te falta Espinas."] = "Il vous manque Épines.",
	["Te falta Fuego interior: más armadura."] = "Il vous manque Feu intérieur : plus d'armure.",
	["Te falta Grito de batalla: más poder de ataque para ti y tu grupo."] = "Il vous manque Cri de guerre : plus de puissance d'attaque pour vous et votre groupe.",
	["Te falta Intelecto Arcano: más maná."] = "Il vous manque Intelligence des Arcanes : plus de mana.",
	["Te falta Marca de lo Salvaje."] = "Il vous manque Marque du fauve.",
	["Te falta Palabra de poder: entereza: más vida."] = "Il vous manque Mot de pouvoir : Robustesse : plus de vie.",
	["Te falta ira: Ira sangrienta te la da gratis."] = "Vous manquez de rage : Rage sanguinaire vous en donne gratuitement.",
	["Te falta la profesión"] = "Métier requis",
	["Te falta reputación"] = "Réputation insuffisante",
	["Te faltan %d niveles para tomarla."] = "Encore %d niveaux avant de pouvoir la prendre.",
	["Te faltan %d pasos"] = "Encore %d étapes",
	["Te faltan %s XP para el nivel %d"] = "%s XP avant le niveau %d",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "Encore %s XP avant le niveau %d, à votre rythme actuel.",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "Il vous manque des niveaux pour atteindre le %d : le guide vous l'indique et vous continuez à monter avec votre itinéraire.",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "Il vous manque des niveaux : chaque niveau à partir du 10 vous donne un point.",
	["Te la da %s, en %s."] = "%s vous la donne, à %s.",
	["Te la da %s."] = "%s vous la donne.",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "Vous mène aux quêtes de votre itinéraire que vous pouvez déjà prendre.",
	["Te llevo a %s"] = "Je vous mène à %s",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "Je vous mène à la meilleure source. N'oubliez pas qu'une monture demande un niveau, la monte et de l'or.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "Je vous mène à celui qui reçoit chacune, et vous récupérez les suivantes.",
	["Te lo da un PNJ"] = "Donné par un PNJ",
	["Te lo enseña tu entrenador."] = "Votre maître vous l'enseigne.",
	["Te los enseña tu entrenador."] = "Votre maître vous les enseigne.",
	["Te queda 1 espacio"] = "Il vous reste 1 emplacement",
	["Te queda poca XP descansada"] = "Il vous reste peu d'XP de repos",
	["Te queda poco maná: cambia vida por maná."] = "Vous manquez de mana : échangez de la vie contre du mana.",
	["Te quedan %d de %d espacios"] = "Il vous reste %d emplacements sur %d",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "Vous avez de la rage en trop et plusieurs ennemis : votre prochain coup en touche deux.",
	["Te sobra ira: gástala en tu siguiente golpe."] = "Vous avez de la rage en trop : dépensez-la dans votre prochain coup.",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "Vous avez de la rage en trop : votre prochain coup est plus puissant.",
	["Tecla para pescar"] = "Touche de pêche",
	["Tela"] = "Tissu",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "Ayez toujours une potion de soins sous la main : ce build ne pardonne pas les erreurs.",
	["Terminaste %d de sus misiones: entrégalas y recoge las que siguen."] = "Vous avez terminé %d de ses quêtes : rendez-les et récupérez les suivantes.",
	["Terminaste 1 de sus misiones: entrégala y recoge las que siguen."] = "Vous avez terminé 1 de ses quêtes : rendez-la et récupérez les suivantes.",
	["Terminaste esta guía."] = "Vous avez terminé ce guide.",
	["Terminaste esta guía. Elige la siguiente para seguir subiendo."] = "Vous avez terminé ce guide. Choisissez le suivant pour continuer à monter.",
	["Tesoro"] = "Trésor",
	["Tesoros"] = "Trésors",
	["Tesoros en el mapa"] = "Trésors sur la carte",
	["Tesoros en el minimapa"] = "Trésors sur la minicarte",
	["Tiempo"] = "Temps",
	["Tiempo de juego por sesión"] = "Temps de jeu par session",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "Délai maximal entre les deux clics. Augmentez-le si vos doubles-clics ne lancent pas la ligne.",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "Il a quatre parties qui se font séparément : Cimetière, Bibliothèque, Armurerie et Cathédrale, de la plus facile à la plus difficile.",
	["Tienes"] = "Vous avez",
	["Tienes %d"] = "Vous en avez %d",
	["Tienes %d  ·  en %s"] = "Vous en avez %d  ·  dans %s",
	["Tienes %d casillas libres"] = "Vous avez %d emplacements libres",
	["Tienes %d de %d casillas de bolsa en el banco."] = "Vous avez %d emplacements de sac sur %d à la banque.",
	["Tienes %d de %d casillas de bolsa. La siguiente cuesta %s; después pon una bolsa en ella."] = "Vous avez %d emplacements de sac sur %d. Le suivant coûte %s ; placez-y ensuite un sac.",
	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "Vous en avez %d activées. Chacune est plus bas, avec ce qu'elle fait, si vous voulez changer quelque chose.",
	["Tienes %d misiones listas para entregar"] = "Vous avez %d quêtes prêtes à rendre",
	["Tienes %d puntos de talento: empieza por %s"] = "Vous avez %d points de talent : commencez par %s",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "Vous avez %d points hors de %s. Alfa ne retire jamais de talents : pour suivre ce build, réinitialisez vos talents auprès de votre maître de classe et Alfa les replace en un clic. Ou choisissez le build de la branche que vous avez déjà.",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "Vous avez %d points libres, mais les prochains talents de %s n'existent pas dans votre arbre (un patch les a peut-être modifiés). Placez-les à la main dans la fenêtre du jeu ou essayez un autre style.",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "Vous avez %s prix issus de vos recherches. Pour tous les connaître, scannez à l'hôtel des ventes.",
	["Tienes 1 misión lista para entregar"] = "Vous avez 1 quête prête à rendre",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "Vous avez 5 points de combo : le coup de grâce le plus puissant.",
	["Tienes 5 puntos de combo: muerde fuerte."] = "Vous avez 5 points de combo : mordez fort.",
	["Tienes 6 guías abiertas"] = "Vous avez 6 guides ouverts",
	["Tienes activado \"Rechazar invitaciones de hermandad\" en Comodidades: apágalo para que te llegue la invitación."] = "« Refuser les invitations de guilde » est activé dans Confort de jeu : désactivez-le pour recevoir l'invitation.",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "Vous avez des changements non confirmés dans la fenêtre des talents : ils sont annulés avant l'application.",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "Vous avez activé « seulement les quêtes de mon itinéraire » : seules les quêtes de votre itinéraire sont acceptées.",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "Vous avez de la rage : utilisez-le avant le prochain combat, il vous donne, à vous et à votre groupe, plus de puissance d'attaque.",
	["Tienes habilidades nuevas"] = "Vous avez de nouvelles compétences",
	["Tienes la %s, %d versiones atrás."] = "Votre version : %s, avec %d versions de retard.",
	["Tienes la %s."] = "Votre version : %s.",
	["Tienes más rangos de los que pide tu build."] = "Vous avez plus de rangs que n'en demande votre build.",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "Vous avez des points hors du plan : Alfa ne les retire pas, il ne fait qu'ajouter.",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "Vous avez six guides ouverts : fermez-en un et réessayez.",
	["Tienes todo %s"] = "%s est au complet",
	["Tienes un punto de talento: %s"] = "Vous avez un point de talent : %s",
	["Tienes una misión de clase"] = "Vous avez une quête de classe",
	["Tipo"] = "Type",
	["Toca ahora"] = "Maintenant",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "Basculez l'interrupteur pour en ajouter ou en retirer une ; vos choix l'emportent sur le filtre.",
	["Toda calidad"] = "Toutes les qualités",
	["Toda la cuenta"] = "Tout le compte",
	["Toda ranura"] = "Tous les emplacements",
	["Todas"] = "Tous",
	["Todas las guías de profesiones"] = "Tous les guides de métiers",
	["Todas las guías por zona y nivel, con la que Alfa te sugiere para ti."] = "Tous les guides par zone et par niveau, avec celui qu'Alfa vous suggère.",
	["Todas las mazmorras"] = "Tous les donjons",
	["Todas las que encuentre"] = "Toutes celles qu'il trouve",
	["Todas las zonas y razas"] = "Toutes les zones et races",
	["Todavía es pronto"] = "C'est encore tôt",
	["Todavía no"] = "Pas encore",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "Vous ne connaissez pas encore ses sorts : ils se remplissent à mesure que vous les apprenez.",
	["Todavía no conozco tus recetas"] = "Je ne connais pas encore vos recettes",
	["Todavía no es para ti"] = "Pas encore pour vous",
	["Todavía no estás en una hermandad. En la página La Jauría ves cómo unirte a la manada."] = "Vous n'êtes pas encore dans une guilde. La page La Jauría vous montre comment rejoindre la meute.",
	["Todavía no has pescado nada"] = "Vous n'avez encore rien pêché",
	["Todavía no hay ayuda de rotación para ti"] = "Pas encore d'aide à la rotation pour vous",
	["Todavía no hay datos de este personaje"] = "Pas encore de données pour ce personnage",
	["Todavía no hay datos para esta gráfica."] = "Pas encore de données pour ce graphique.",
	["Todavía no hay foto de este banco"] = "Pas encore de relevé de cette banque",
	["Todavía no hay peleas"] = "Pas encore de combats",
	["Todavía no hay progreso"] = "Pas encore de progression",
	["Todavía no hay una pelea anterior"] = "Pas encore de combat précédent",
	["Todavía no hay una pelea que anunciar."] = "Pas encore de combat à annoncer.",
	["Todavía no lo recolectas"] = "Pas encore récolté",
	["Todavía no puedes conseguirlo: %s."] = "Vous ne pouvez pas encore l'obtenir : %s.",
	["Todavía no recolectas nada"] = "Vous n'avez encore rien récolté",
	["Todavía no sabes pescar"] = "Vous ne savez pas encore pêcher",
	["Todavía no se puede tomar: Alfa la recoge cuando se abra."] = "Elle ne peut pas encore être prise : Alfa la récupérera dès qu'elle s'ouvrira.",
	["Todavía no sigues ninguna guía. Elige una y Alfa te lleva paso a paso, con la flecha y la ruta."] = "Vous ne suivez encore aucun guide. Choisissez-en un et Alfa vous guide pas à pas, avec la flèche et l'itinéraire.",
	["Todavía no te alcanza."] = "Vous n'avez pas encore assez.",
	["Todavía no tienes escalas propias. Pega una cadena de escala arriba."] = "Vous n'avez pas encore d'échelles à vous. Collez une chaîne d'échelle ci-dessus.",
	["Todavía no tienes marcadores"] = "Vous n'avez pas encore de marqueurs",
	["Todavía no tienes rutas propias"] = "Vous n'avez pas encore d'itinéraires à vous",
	["Todavía no tienes talentos para compartir."] = "Vous n'avez pas encore de talents à partager.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "Vous n'avez pas encore de guide ouvert. Choisissez-en un et Alfa vous guide pas à pas : où aller, quoi faire et à qui parler.",
	["Todo"] = "Tout",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "Tout Azeroth sur une seule toile : zoomez avec la molette, faites glisser pour vous déplacer et placez vos marqueurs d'un clic droit.",
	["Todo bien (lo más gastado: %d%%)"] = "Tout va bien (le plus usé : %d%%)",
	["Todo el juego, aunque no lo tengas"] = "Tout le jeu, même ce que vous n'avez pas",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "Tout le jeu, même ce que vous n'avez pas : objets, PNJ, quêtes, zones et rares.",
	["Todo en orden"] = "Tout va bien",
	["Todo junto"] = "Tout ensemble",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "Tout ensemble montre chaque emplacement à sa place ; par catégorie regroupe équipement, consommables, quêtes et matériaux ; par sac place chaque sac dans son bloc.",
	["Todo listo"] = "Tout est prêt",
	["Todo lo que no sea equipo"] = "Tout ce qui n'est pas de l'équipement",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "Tout ce qui est dessiné sur vos cartes, au même endroit. Ce qu'ajoutent les autres modules d'Alfa arrive aussi ici.",
	["Todo nivel"] = "Tous les niveaux",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "Chaque objet, PNJ, quête, zone et rare, avec où l'obtenir et « Me guider ».",
	["Todo oficio"] = "Tous les rôles",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "Tout pour les dégâts : critiques, saignements et Fulgurance très souvent. Vous tuez à toute vitesse, mais sans défense en plus : si beaucoup d'ennemis s'en prennent à vous, fuyez.",
	["Todo subtipo"] = "Tous les sous-types",
	["Todo tipo"] = "Tous les types",
	["Todos"] = "Tous",
	["Todos llegan a %s"] = "Tous mènent à %s",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "Tous ceux de ce type, ou un seul (par exemple, seulement le cuivre). Entre parenthèses, combien il y en a dans votre zone.",
	["Todos los materiales"] = "Tous les matériaux",
	["Todos los niveles"] = "Tous les niveaux",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Tous les objets, PNJ, quêtes, zones et rares, même ceux que vous n'avez pas : qui le laisse tomber et à quelle fréquence, qui le vend et où, quelle quête le donne et comment y aller.",
	["Todos los pasos"] = "Toutes les étapes",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "Toutes les étapes de ce guide ; cliquez sur l'une d'elles pour la voir.",
	["Todos los pasos de la guía en la ventana de guía."] = "Toutes les étapes du guide, dans la fenêtre du guide.",
	["Todos los tipos"] = "Tous les types",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "Tous vos points sont déjà dépensés, dont une partie hors de ce build. Pour passer à ce build, réinitialisez vos talents auprès de votre maître de classe ; ensuite, Alfa vous les applique en un clic.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "Tous : les alertes mineures aussi. Seulement les graves : uniquement ce qui peut vous tuer.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "Ramasse le butin de pêche tout de suite, même si la fouille automatique du jeu est désactivée.",
	["Toma las de tu ruta que tienes cerca"] = "Prenez les quêtes de votre itinéraire à proximité",
	["Toma las mejores de cerca que ya puedes hacer."] = "Prenez les meilleures quêtes proches que vous pouvez déjà faire.",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "Prenez les meilleures quêtes du coin, puis terminez-les ensemble.",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "Prenez quelques quêtes proches et Alfa les termine avec vous par le chemin le plus court.",
	["Tomaste otra misión de su grupo: esta ya no se abre."] = "Vous avez pris une autre quête de son groupe : celle-ci ne s'ouvrira plus.",
	["Top %d de %s"] = "Top %d %s",
	["Top de daño"] = "Top des dégâts",
	["Tortura mental: daño constante y frena al enemigo."] = "Fouet mental : dégâts constants et ralentit l'ennemi.",
	["Tramo %d de %d: %s."] = "Tronçon %d sur %d : %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "Pièges, coups au corps à corps d'urgence et beaucoup d'agilité : le chasseur le plus difficile à attraper.",
	["Tranquilo"] = "Prudent",
	["Transformar"] = "Transformer",
	["Transformar %d"] = "Transformer %d",
	["Tratado"] = "Libram",
	["Tres caminos para cada objeto"] = "Trois options pour chaque objet",
	["Tres estilos y el lobo"] = "Trois styles et le loup",
	["Tres pasos y listo"] = "Trois étapes et c'est prêt",
