	["Tu arma no tiene encantamiento: Viento furioso."] = "Votre arme n'a pas d'enchantement : Furie-des-vents.",
	["Tu arma no usa munición."] = "Votre arme n'utilise pas de munitions.",
	["Tu arma secundaria pega más."] = "Votre arme en main gauche frappe plus fort.",
	["Tu avance arriba, el paso en una tarjeta, los dos siguientes a la vista y los botones abajo."] = "Votre progression en haut, l'étape sur une carte, les deux suivantes en vue et les boutons en bas.",
	["Tu ayuda de rotación está lista"] = "Votre aide à la rotation est prête",
	["Tu banco"] = "Votre banque",
