	["Tu clase no necesita recordatorio"] = "Votre classe n'a pas besoin de rappel",
	["Tu clase no tiene habilidades de reacción. Si quieres, Alfa te avisa cuando el juego hace brillar una de tus habilidades (en Avisos, abajo)."] = "Votre classe n'a pas de techniques de réaction. Si vous voulez, Alfa vous prévient quand le jeu fait briller une de vos techniques (dans Alertes, plus bas).",
	["Tu clase todavía no tiene uno propio: Alfa usa el más parecido."] = "Votre classe n'en a pas encore un à elle : Alfa utilise le plus proche.",
	["Tu cliente no deja cambiar talentos desde un addon. Usa la ventana de talentos del juego (tecla N)."] = "Votre client ne permet pas à un addon de changer les talents. Utilisez la fenêtre des talents du jeu (touche N).",
	["Tu cliente no tiene la línea de tiempo de jefes."] = "Votre client n'a pas la chronologie des boss.",
